  triant:{a:'Triantafyllopoulos et al. 2026',t:'Conceptors for Semantic Steering',x:'2605.04980'},
  angular:{a:'Vu & Nguyen 2025',t:'Angular Steering: Behavior Control via Rotation in Activation Space',x:'2510.26243'},
