Object.values(REF).forEach(r=>{if(!r.url)r.url='https://arxiv.org/abs/'+r.x});
const escH=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
// cite('mimic') -> a link to the paper itself, opening in a new tab; cite('mimic','MiMiC') uses that link text
function cite(k,txt){const r=REF[k];if(!r)throw new Error('unknown reference '+k);return`<a href="${r.url}" target="_blank" rel="noopener" title="${escH(r.t)}">${txt||r.a}</a>`}
// body links are written <a data-ref="key">text</a>; this fills in the address, so every link comes from REF
function linkRefs(root=document){root.querySelectorAll('a[data-ref]').forEach(a=>{const r=REF[a.dataset.ref];if(!r)throw new Error('unknown reference '+a.dataset.ref);
  a.href=r.url;a.target='_blank';a.rel='noopener';a.title=r.t;if(!a.textContent.trim())a.textContent=r.a})}

/* ================= colors ================= */
const COL={};
function loadCols(){const cs=getComputedStyle(document.documentElement);['persona','assist','drift','edit','navy','gold','ink','muted','hair','grid','violet','ochre','paper','panel','sunk','olive'].forEach(k=>COL[k]=cs.getPropertyValue('--'+k).trim())}
function A(hex,a){const h=hex.replace('#','');const n=parseInt(h,16);return`rgba(${n>>16&255},${n>>8&255},${n&255},${a})`}
const FONT=()=>getComputedStyle(document.body).fontFamily;

/* ================= UI helpers ================= */
const $=s=>document.querySelector(s);
function seg(id,opts,val,on){const el=$(id);el.innerHTML='';opts.forEach(([v,l])=>{const b=document.createElement('button');b.type='button';b.textContent=l;b.setAttribute('aria-pressed',String(v===val));
  b.addEventListener('click',()=>{[...el.children].forEach(c=>c.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');on(v)});el.appendChild(b)})}
function slider(id,fmt,on){const el=$('#'+id),out=$('#'+id.replace(/^r/,'o'));const upd=()=>{out.textContent=fmt(+el.value);on(+el.value)};el.addEventListener('input',upd);out.textContent=fmt(+el.value);return()=>+el.value}
function reads(id,items){$(id).innerHTML=items.map(([v,l])=>`<div><b>${v}</b><span>${l}</span></div>`).join('')}
// redraw on resize, and once right after setup even if no resize callback ever arrives (hidden pages, thumbnails)
function watch(el,fn){const ro=new ResizeObserver(()=>fn());ro.observe(el);setTimeout(fn,0);return ro}
function fitCanvas(c,g){const r=c.getBoundingClientRect();if(!r.width)return null;const dpr=window.devicePixelRatio||1;c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,r.width,r.height);return r}
function arrowPx(g,x0,y0,x1,y1,col,w=1.4,head=6){const L=Math.hypot(x1-x0,y1-y0);if(L<1.5)return;g.save();g.strokeStyle=col;g.fillStyle=col;g.lineWidth=w;g.beginPath();g.moveTo(x0,y0);g.lineTo(x1,y1);g.stroke();
  const an=Math.atan2(y1-y0,x1-x0);const h=Math.min(head,L*.6);g.beginPath();g.moveTo(x1,y1);g.lineTo(x1-h*Math.cos(an-.42),y1-h*Math.sin(an-.42));g.lineTo(x1-h*Math.cos(an+.42),y1-h*Math.sin(an+.42));g.closePath();g.fill();g.restore()}

/* ================= 2D plot ================= */
class Plot2D{
  constructor(canvas,box,draw){this.c=canvas;this.g=canvas.getContext('2d');this.box=box;this.draw=draw;this.handles=[];this.drag=null;
    const pt=e=>{const r=canvas.getBoundingClientRect();return[e.clientX-r.left,e.clientY-r.top]};
    canvas.addEventListener('pointerdown',e=>{const p=pt(e);for(const h of this.handles){const s=this.S(h.get());if(Math.hypot(s[0]-p[0],s[1]-p[1])<20){this.drag=h;canvas.setPointerCapture(e.pointerId);e.preventDefault();return}}});
    canvas.addEventListener('pointermove',e=>{if(!this.drag)return;const p=pt(e);const w=this.Wd(p[0],p[1]);const b=this.box;
      w[0]=clamp(w[0],b.x0,b.x1);w[1]=clamp(w[1],b.y0,b.y1);this.drag.set(w);this.draw()});
    const end=()=>{this.drag=null};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
    watch(canvas,()=>{this.resize();this.draw()})}
  resize(){const r=this.c.getBoundingClientRect();if(!r.width)return;const dpr=window.devicePixelRatio||1;this.W=r.width;this.H=r.height;
    this.c.width=Math.round(this.W*dpr);this.c.height=Math.round(this.H*dpr);this.g.setTransform(dpr,0,0,dpr,0,0);
    const b=this.box;const s=Math.min(this.W/(b.x1-b.x0),this.H/(b.y1-b.y0));this.s=s;this.ox=this.W/2-s*(b.x0+b.x1)/2;this.oy=this.H/2+s*(b.y0+b.y1)/2}
  // measure on first use too: a ResizeObserver callback can be late or missing in a hidden or background page
  ready(){if(!(this.W>0))this.resize();return this.W>0}
  S(p){return[this.ox+this.s*p[0],this.oy-this.s*p[1]]}
  Wd(x,y){return[(x-this.ox)/this.s,(this.oy-y)/this.s]}
  clear(){this.g.clearRect(0,0,this.W,this.H);const g=this.g;g.strokeStyle=COL.grid;g.lineWidth=1;const b=this.box;
    for(let x=Math.ceil(b.x0);x<=b.x1;x++){const a=this.S([x,b.y0]),c=this.S([x,b.y1]);g.beginPath();g.moveTo(a[0],a[1]);g.lineTo(c[0],c[1]);g.stroke()}
    for(let y=Math.ceil(b.y0);y<=b.y1;y++){const a=this.S([b.x0,y]),c=this.S([b.x1,y]);g.beginPath();g.moveTo(a[0],a[1]);g.lineTo(c[0],c[1]);g.stroke()}}
  dot(p,r,fill,stroke,lw=1.5){const s=this.S(p),g=this.g;g.beginPath();g.arc(s[0],s[1],r,0,2*Math.PI);if(fill){g.fillStyle=fill;g.fill()}if(stroke){g.strokeStyle=stroke;g.lineWidth=lw;g.stroke()}}
  line(a,b,col,w=1,dash){const g=this.g,s=this.S(a),t=this.S(b);g.save();g.strokeStyle=col;g.lineWidth=w;if(dash)g.setLineDash(dash);g.beginPath();g.moveTo(s[0],s[1]);g.lineTo(t[0],t[1]);g.stroke();g.restore()}
  path(pts,col,w=1.6,dash){const g=this.g;g.save();g.strokeStyle=col;g.lineWidth=w;if(dash)g.setLineDash(dash);g.beginPath();pts.forEach((p,i)=>{const s=this.S(p);i?g.lineTo(s[0],s[1]):g.moveTo(s[0],s[1])});g.stroke();g.restore()}
  arrow(a,b,col,w=1.4,head=6){const s=this.S(a),t=this.S(b);arrowPx(this.g,s[0],s[1],t[0],t[1],col,w,head)}
  ellipse(c,vecs,axes,col,{w=1.6,dash=null,fill=null}={}){const g=this.g;g.save();g.beginPath();
    for(let i=0;i<=72;i++){const t=i/72*2*Math.PI;const p=add(c,add(scl(vecs[0],axes[0]*Math.cos(t)),scl(vecs[1],axes[1]*Math.sin(t))));const s=this.S(p);i?g.lineTo(s[0],s[1]):g.moveTo(s[0],s[1])}
    g.closePath();if(fill){g.fillStyle=fill;g.fill()}g.strokeStyle=col;g.lineWidth=w;if(dash)g.setLineDash(dash);g.stroke();g.restore()}
  covEllipse(c,S,k,col,opt){const{vals,vecs}=symEig(S);this.ellipse(c,vecs,vals.map(v=>k*Math.sqrt(Math.max(v,0))),col,opt)}
  halfplane(n,tau,fill){const b=this.box;let poly=[[b.x0,b.y0],[b.x1,b.y0],[b.x1,b.y1],[b.x0,b.y1]];const out=[];
    for(let i=0;i<poly.length;i++){const a=poly[i],c=poly[(i+1)%poly.length];const fa=dot(n,a)-tau,fc=dot(n,c)-tau;
      if(fa<=0)out.push(a);if((fa<0&&fc>0)||(fa>0&&fc<0)){const t=fa/(fa-fc);out.push(add(a,scl(sub(c,a),t)))}}
    if(out.length<3)return;const g=this.g;g.beginPath();out.forEach((p,i)=>{const s=this.S(p);i?g.lineTo(s[0],s[1]):g.moveTo(s[0],s[1])});g.closePath();g.fillStyle=fill;g.fill()}
  boundary(n,tau,col,w=1.6,dash,label){const u=unit(n);const p0=scl(u,tau/nrm(n));const t=[-u[1],u[0]];this.line(add(p0,scl(t,-30)),add(p0,scl(t,30)),col,w,dash);
    if(label){const b=this.box;let best=null;for(let k=-30;k<=30;k+=.25){const p=add(p0,scl(t,k));if(p[1]<=b.y1-.25&&p[1]>=b.y0&&p[0]>=b.x0&&p[0]<=b.x1){if(!best||p[1]>best[1])best=p}}if(best)this.text(add(best,[.12,-.05]),label,col,{font:'600 12px'})}}
  text(p,str,col,{align='left',font='500 12px',base='middle',halo=false}={}){const g=this.g,s=this.S(p);g.font=`${font} ${FONT()}`;g.textAlign=align;g.textBaseline=base;
    if(halo){g.save();g.lineWidth=4;g.lineJoin='round';g.strokeStyle=A(COL.paper,.92);g.strokeText(str,s[0],s[1]);g.restore()}g.fillStyle=col;g.fillText(str,s[0],s[1])}
  ring(p){this.dot(p,9,A(COL.paper,.85),COL.ink,2);this.dot(p,3,COL.ink)}
}

/* ================= 3D plot ================= */
class Plot3D{
  constructor(canvas,draw,{yaw=-.62,pitch=.38,span=5.2}={}){this.c=canvas;this.g=canvas.getContext('2d');this.draw=draw;this.yaw=yaw;this.pitch=pitch;this.span=span;
    let last=null;canvas.addEventListener('pointerdown',e=>{last=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)});
    canvas.addEventListener('pointermove',e=>{if(!last)return;const dx=e.clientX-last[0],dy=e.clientY-last[1];last=[e.clientX,e.clientY];
      this.yaw+=dx*.009;this.pitch=clamp(this.pitch+dy*.009,-1.45,1.45);this.draw()});
    const end=()=>{last=null};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
    canvas.addEventListener('keydown',e=>{const k={ArrowLeft:[-.12,0],ArrowRight:[.12,0],ArrowUp:[0,-.12],ArrowDown:[0,.12]}[e.key];if(k){this.yaw+=k[0];this.pitch=clamp(this.pitch+k[1],-1.45,1.45);this.draw();e.preventDefault()}});
    watch(canvas,()=>{this.resize();this.draw()})}
  resize(){const r=this.c.getBoundingClientRect();if(!r.width)return;const dpr=window.devicePixelRatio||1;this.W=r.width;this.H=r.height;
    this.c.width=Math.round(this.W*dpr);this.c.height=Math.round(this.H*dpr);this.g.setTransform(dpr,0,0,dpr,0,0);this.s=Math.min(this.W,this.H)/(2*this.span);this.cx=this.W/2;this.cy=this.H/2;this._fk=null}
  ready(){if(!(this.W>0))this.resize();return this.W>0}
  P(p){const cy=Math.cos(this.yaw),sy=Math.sin(this.yaw);const X=cy*p[0]-sy*p[1],Y=sy*p[0]+cy*p[1],Z=p[2];
    const cp=Math.cos(this.pitch),sp=Math.sin(this.pitch);const Y2=cp*Y+sp*Z,Z2=-sp*Y+cp*Z;return[this.cx+this.s*X,this.cy-this.s*Z2,Y2]}
  clear(){this.g.clearRect(0,0,this.W,this.H)}
  poly(pts,col,w=1,{close=false,dash=null,fill=null}={}){const g=this.g;g.save();g.beginPath();pts.forEach((p,i)=>{const s=this.P(p);i?g.lineTo(s[0],s[1]):g.moveTo(s[0],s[1])});if(close)g.closePath();
    if(fill){g.fillStyle=fill;g.fill()}if(col){g.strokeStyle=col;g.lineWidth=w;if(dash)g.setLineDash(dash);g.stroke()}g.restore()}
  arrow(a,b,col,w=2,head=9){const s=this.P(a),t=this.P(b);arrowPx(this.g,s[0],s[1],t[0],t[1],col,w,head)}
  bbox(pts){let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;pts.forEach(p=>{const s=this.P(p);x0=Math.min(x0,s[0]);x1=Math.max(x1,s[0]);y0=Math.min(y0,s[1]);y1=Math.max(y1,s[1])});return{x0,x1,y0,y1}}
  // centre the points; once per canvas size, also zoom so they fill the canvas at every yaw, so turning never clips them
  fit(pts){this.cx=0;this.cy=0;const key=this.W+'x'+this.H;
    if(this._fk!==key){this._fk=key;const y0=this.yaw;let k=Infinity;
      for(let i=0;i<8;i++){this.yaw=y0+i*Math.PI/4;const b=this.bbox(pts);k=Math.min(k,this.W*.9/Math.max(b.x1-b.x0,1e-6),this.H*.84/Math.max(b.y1-b.y0,1e-6))}
      this.yaw=y0;this.s*=k}
    const b=this.bbox(pts);this.cx=this.W/2-(b.x0+b.x1)/2;this.cy=this.H/2-(b.y0+b.y1)/2}
  label(x,y,str,col){const g=this.g;g.fillStyle=col;g.font=`600 12px ${FONT()}`;g.textAlign='left';g.textBaseline='middle';g.fillText(str,x,y)}
  text(p,str,col,font='600 12px'){const s=this.P(p),g=this.g;g.font=`${font} ${FONT()}`;g.textAlign='center';g.textBaseline='middle';
    g.save();g.lineWidth=4;g.lineJoin='round';g.strokeStyle=A(COL.paper,.92);g.strokeText(str,s[0],s[1]);g.restore();g.fillStyle=col;g.fillText(str,s[0],s[1])}
  points(list){const pr=list.map(o=>({o,s:this.P(o.p)}));pr.sort((a,b)=>b.s[2]-a.s[2]);const g=this.g;
    for(const{o,s}of pr){g.beginPath();g.arc(s[0],s[1],o.r||2.6,0,2*Math.PI);if(o.fill){g.fillStyle=o.fill;g.fill()}if(o.stroke){g.strokeStyle=o.stroke;g.lineWidth=o.lw||1.2;g.stroke()}}}
  ellipsoid(c,vecs,axes,col){const pt=(u,v)=>add(c,add(add(scl(vecs[0],axes[0]*Math.cos(v)*Math.cos(u)),scl(vecs[1],axes[1]*Math.cos(v)*Math.sin(u))),scl(vecs[2],axes[2]*Math.sin(v))));
    for(const v of[-1,-.5,0,.5,1]){const ring=[];for(let i=0;i<=48;i++)ring.push(pt(i/48*2*Math.PI,v));this.poly(ring,col,1)}
    for(let m=0;m<6;m++){const u=m/6*Math.PI;const mer=[];for(let i=0;i<=48;i++)mer.push(pt(u,-Math.PI/2+i/48*2*Math.PI));this.poly(mer,col,1)}}
  // an orientation key pinned to the bottom-left corner: each arrow is a unit axis as this view projects it
  axes3(o,len,labels){const g=this.g,ox=30,oy=this.H-30,L=22,p0=this.P([0,0,0]);
    [[1,0,0],[0,1,0],[0,0,1]].forEach((v,i)=>{const q=this.P(v),dx=(q[0]-p0[0])/this.s,dy=(q[1]-p0[1])/this.s;
      arrowPx(g,ox,oy,ox+L*dx,oy+L*dy,A(COL.muted,.85),1.2,5);g.fillStyle=COL.muted;g.font=`500 11px ${FONT()}`;g.textAlign='center';g.textBaseline='middle';g.fillText(labels[i],ox+(L+9)*dx,oy+(L+9)*dy)})}
}

/* ================= small line chart (real data and reported numbers) ================= */
// spec: {x:{min,max,log,ticks:[..],label,fmt}, y:{min,max,ticks:[..],label,fmt}, series:[{pts:[[x,y]..],col,w,dash,marker,label}], vline:x, notes:[{x,y,text,col,align}]}
function lineChart(c,spec){const g=c.getContext('2d');const r=fitCanvas(c,g);if(!r)return;const W=r.width,H=r.height;const pad={l:44,r:14,t:spec.title?26:12,b:34};
  const fx=v=>spec.x.log?Math.log10(v):v;const X=v=>pad.l+(fx(v)-fx(spec.x.min))/(fx(spec.x.max)-fx(spec.x.min))*(W-pad.l-pad.r);
  const Y=v=>H-pad.b-(v-spec.y.min)/(spec.y.max-spec.y.min)*(H-pad.t-pad.b);const font=FONT();
  g.font=`500 11px ${font}`;g.lineWidth=1;
  spec.y.ticks.forEach(t=>{g.strokeStyle=COL.grid;g.beginPath();g.moveTo(pad.l,Y(t));g.lineTo(W-pad.r,Y(t));g.stroke();g.fillStyle=COL.muted;g.textAlign='right';g.textBaseline='middle';g.fillText(spec.y.fmt?spec.y.fmt(t):String(t),pad.l-6,Y(t))});
  spec.x.ticks.forEach(t=>{g.strokeStyle=COL.grid;g.beginPath();g.moveTo(X(t),pad.t);g.lineTo(X(t),H-pad.b);g.stroke();g.fillStyle=COL.muted;g.textAlign='center';g.textBaseline='top';g.fillText(spec.x.fmt?spec.x.fmt(t):String(t),X(t),H-pad.b+5)});
  g.strokeStyle=COL.hair;g.beginPath();g.moveTo(pad.l,H-pad.b);g.lineTo(W-pad.r,H-pad.b);g.stroke();
  if(spec.x.label){g.fillStyle=COL.muted;g.textAlign='center';g.textBaseline='bottom';g.fillText(spec.x.label,pad.l+(W-pad.l-pad.r)/2,H-1)}
  if(spec.y.label){g.save();g.translate(11,pad.t+(H-pad.t-pad.b)/2);g.rotate(-Math.PI/2);g.textAlign='center';g.textBaseline='middle';g.fillStyle=COL.muted;g.fillText(spec.y.label,0,0);g.restore()}
  if(spec.title){g.fillStyle=COL.ink;g.font=`600 12px ${font}`;g.textAlign='left';g.textBaseline='top';g.fillText(spec.title,pad.l,4);g.font=`500 11px ${font}`}
  if(spec.band){g.fillStyle=spec.band.fill;g.fillRect(X(spec.band.x0),pad.t,X(spec.band.x1)-X(spec.band.x0),H-pad.t-pad.b)}
  if(spec.vline!=null){g.strokeStyle=A(COL.navy,.7);g.setLineDash([4,3]);g.beginPath();g.moveTo(X(spec.vline),pad.t);g.lineTo(X(spec.vline),H-pad.b);g.stroke();g.setLineDash([])}
  spec.series.forEach(s=>{const pts=s.pts.filter(p=>p[1]!=null);if(!pts.length)return;g.save();g.strokeStyle=s.col;g.lineWidth=s.w||2;if(s.dash)g.setLineDash(s.dash);g.beginPath();
    pts.forEach((p,i)=>{const x=X(p[0]),y=Y(p[1]);i?g.lineTo(x,y):g.moveTo(x,y)});g.stroke();g.setLineDash([]);
    if(s.marker)pts.forEach(p=>{g.beginPath();g.arc(X(p[0]),Y(p[1]),s.marker,0,2*Math.PI);g.fillStyle=s.hollow?COL.panel:s.col;g.fill();g.strokeStyle=s.col;g.lineWidth=1.5;g.stroke()});
    if(s.label){const p=pts[pts.length-1];g.fillStyle=s.col;g.font=`600 11px ${font}`;g.textAlign='right';g.textBaseline=s.labelBase||'bottom';g.fillText(s.label,X(p[0])-6,Y(p[1])+(s.labelDy||-4))}
    g.restore()});
  (spec.notes||[]).forEach(n=>{g.fillStyle=n.col||COL.muted;g.font=`${n.font||'500 11px'} ${font}`;g.textAlign=n.align||'left';g.textBaseline='middle';g.fillText(n.text,X(n.x),Y(n.y))});
  return{X,Y,pad,W,H}}

/* ================= shared 2D world (toy) ================= */
// Persona and assistant token clouds share a content direction tilted 32 degrees, so content leaks onto the persona axis.
// The persona's own style spread runs at -28 degrees. Drifted tokens are persona tokens pushed part way back to the assistant.
function makeWorld2D(seed,N=150){const r=mulberry32(seed);const muA=[-2,0],muP=[2,0],dTrue=sub(muP,muA);
  const th=32*Math.PI/180,u1=[Math.cos(th),Math.sin(th)],u2=[-Math.sin(th),Math.cos(th)];
  const ph=-28*Math.PI/180,w1=[Math.cos(ph),Math.sin(ph)],w2=[-Math.sin(ph),Math.cos(ph)];
  const content=()=>add(scl(u1,1.25*randn(r)),scl(u2,.22*randn(r)));
  const styleP=()=>add(scl(w1,.42*randn(r)),scl(w2,.17*randn(r)));
  const styleA=()=>[.2*randn(r),.2*randn(r)];
  const P=[],Ap=[],Dr=[];
  for(let i=0;i<N;i++){const cz=content();P.push(add(add(muP,cz),styleP()));Ap.push(add(add(muA,cz),styleA()))}
  for(let i=0;i<N;i++){const t=.3+.55*r();Dr.push(sub(add(add(muP,content()),styleP()),scl(dTrue,t)))}
  const mP=meanOf(P),mA=meanOf(Ap),d=sub(mP,mA),vhat=unit(d);
  const SigP=covOf(P),SigA=covOf(Ap),SigW=mscl(madd(SigP,SigA),.5);
  const D=P.map((p,i)=>sub(p,Ap[i]));
  return{P,A:Ap,Dr,mP,mA,d,vhat,SigP,SigA,SigW,D,u1,w1}}
const W2=makeWorld2D(11);
const ZERO=[0,-3.4];             // where the zero vector sits in this picture, for moves that keep a token's length
const SPi_W2=inv(W2.SigP);
const sCoord=h=>dot(sub(h,W2.mA),W2.d)/dot(W2.d,W2.d);
const inside2s=h=>{const q=sub(h,W2.mP);return dot(q,mv(SPi_W2,q))<=4};
function metrics(edit){const Pe=W2.P.map(edit),De=W2.Dr.map(edit);
  const sb=avg(W2.Dr.map(sCoord)),sa=avg(De.map(e=>sCoord(e.h)));
  const spread=Math.sqrt(avg(W2.P.map(h=>{const q=sub(h,W2.mP);return dot(q,q)})));
  const dist=Math.sqrt(avg(Pe.map((e,i)=>{const q=sub(e.h,W2.P[i]);return dot(q,q)})))/spread;
  const normCh=avg(De.map((e,i)=>nrm(sub(e.h,ZERO))/nrm(sub(W2.Dr[i],ZERO))-1));
  return{restore:(sa-sb)/(1-sb),dist,caught:avg(De.map(e=>e.on?1:0)),ftr:avg(Pe.map(e=>e.on?1:0)),normCh,landed:avg(De.map(e=>inside2s(e.h)?1:0)),Pe,De}}
const BOX2={x0:-5.6,x1:5.8,y0:-3.7,y1:3.7};
function drawClouds(pl,{assist=true,persona=true,drift=true,af=.28}={}){
  if(assist)W2.A.forEach(p=>pl.dot(p,2.3,A(COL.assist,af)));
  if(persona)W2.P.forEach(p=>pl.dot(p,2.6,A(COL.persona,.75)));
  if(drift)W2.Dr.forEach(p=>pl.dot(p,2.6,A(COL.drift,.75)))}
function drawAxis(pl){pl.line(add(W2.mA,scl(W2.d,-.45)),add(W2.mP,scl(W2.d,.32)),A(COL.navy,.55),1.2,[5,4]);
  pl.dot(W2.mA,4.5,COL.assist,COL.paper,1.5);pl.dot(W2.mP,4.5,COL.persona,COL.paper,1.5)}
// drawn last, over the dots, so the two labels stay readable
function axisLabels(pl){[[W2.mA,'assistant mean',COL.assist],[W2.mP,'persona mean',COL.persona]].forEach(([p,t,c])=>{
  pl.dot(p,4.5,c,COL.paper,1.5);pl.text(add(p,[0,-.5]),t,c,{align:'center',font:'600 13px',halo:true})})}
// One picture for every toy move. Assistant tokens are a fixed, faint reference. In-character tokens stay where they are,
// with a dark ring when the move shifts them too (darker the further it shifts them; the distortion readout says how far).
// Drifted tokens are drawn where the move puts them, with a faint ghost where they started and an arrow on every third.
const shift=(a,b)=>nrm(sub(a,b))/nrm(W2.d);
function drawMove(pl,m,{every=4,assist=true}={}){
  if(assist)W2.A.forEach(p=>pl.dot(p,2.2,A(COL.assist,.24)));
  W2.P.forEach((p,i)=>{const s=shift(m.Pe[i].h,p);pl.dot(p,2.6,A(COL.persona,.72),s>.01?A(COL.ink,.2+.45*Math.min(1,s/.3)):null,1)});
  W2.Dr.forEach((p,i)=>{if(shift(m.De[i].h,p)>.01)pl.dot(p,2.3,A(COL.drift,.16))});
  W2.Dr.forEach((p,i)=>{if(i%every===0&&shift(m.De[i].h,p)>.01)pl.arrow(p,m.De[i].h,A(COL.edit,.7),1.3,6)});
  m.De.forEach(e=>pl.dot(e.h,2.8,A(COL.drift,.85)));axisLabels(pl)}
linkRefs();

/* ================= what we ran: vector and cap ================= */
(function(){let mode='cap',pc=25,c=1;const probe={p:[0.2,-0.9]};
  const projP=W2.P.map(h=>dot(h,W2.vhat)).sort((a,b)=>a-b);
  const tau=()=>quantile(projP,pc/100);
  const edit=h=>{if(mode==='none')return{h,on:false};if(mode==='vector')return{h:add(h,scl(W2.d,c)),on:true};
    const p=dot(h,W2.vhat),t=tau();return p<t?{h:add(h,scl(W2.vhat,t-p)),on:true}:{h,on:false}};
  const pl=new Plot2D($('#c1'),BOX2,draw);pl.handles.push({get:()=>probe.p,set:w=>probe.p=w});
  function draw(){if(!pl.ready())return;loadCols();pl.clear();
    if(mode==='cap'){pl.halfplane(W2.vhat,tau(),A(COL.navy,.06));pl.boundary(W2.vhat,tau(),COL.navy,1.8,null,'floor τ')}
    drawAxis(pl);const m=metrics(edit);drawMove(pl,m);
    const e=edit(probe.p);pl.ring(probe.p);if(e.on)pl.arrow(probe.p,e.h,COL.edit,2.4,9);
    reads('#m1',[[pct(m.restore),'restore (drifted)'],[f2(m.dist),'distortion (in character)'],[pct(m.caught),'drifted tokens edited'],[pct(m.ftr),'in-character tokens edited']])}
  seg('#s1',[['none','No steering'],['vector','Vector'],['cap','Cap']],mode,v=>{mode=v;draw()});
  slider('r1t',v=>v+'th',v=>{pc=v;draw()});slider('r1c',v=>(v/100).toFixed(2),v=>{c=v/100;draw()});
})();

/* ================= what we ran: the aperture, on real SmolLM3 activations ================= */
(function(){const S=DATA.spectrum,L=S.lam_over_median,Wv=S.vhat_weight,E=S.gap_energy,n=L.length;
  const sw=Wv.reduce((a,b)=>a+b,0),se=E.reduce((a,b)=>a+b,0);
  const kOf=v=>Math.pow(10,v/100);
  const keepAxis=k=>{let s=0;for(let i=0;i<n;i++)s+=Wv[i]*L[i]/(L[i]+k);return s/sw};
  const gapKept=k=>{let s=0;for(let i=0;i<n;i++){const g=L[i]/(L[i]+k);s+=E[i]*g*g}return s/se};
  const nKept=k=>{let c=0;for(let i=0;i<n;i++)if(L[i]>k)c++;return c};
  const NB=44,lgn=Math.log10(n);const bin=i=>Math.min(NB-1,Math.floor(Math.log10(i+1)/lgn*NB));
  const wb=Array(NB).fill(0),eb=Array(NB).fill(0);for(let i=0;i<n;i++){wb[bin(i)]+=Wv[i]/sw;eb[bin(i)]+=E[i]/se}
  const KS=[1,3,10,30,100];
  const SEL=[['smol','SmolLM3, 5 personas'],['smol:pirate','pirate'],['smol:ghost','ghost'],['smol:bard','bard'],['smol:genie','genie'],['smol:alien','alien'],
    ['olmo','OLMo, 2 personas'],['olmo:pirate','OLMo pirate'],['olmo:genie','OLMo genie']];
  let k=kOf(100),sel='smol';
  function view(id){const[model,p]=id.split(':');const ap=DATA.aperture[model];const ps=p?[p]:Object.keys(ap);
    const at=(kk,key)=>{const v=ps.map(q=>ap[q][String(kk)]).filter(Boolean).map(c=>c[key]);return v.length===ps.length?avg(v):null};
    const judges=kk=>Math.min(...ps.map(q=>ap[q][String(kk)]?ap[q][String(kk)].judges:0));
    // the all-persona view reads the same rounded means as the comparison table, so the two never disagree
    const ref=(m,key)=>{if(!p&&DATA.means[model][m])return DATA.means[model][m][key];const v=ps.map(q=>ap[q].ref&&ap[q].ref[m]?ap[q].ref[m][key]:null).filter(x=>x!=null);return v.length===ps.length?avg(v):null};
    return{at,judges,ref,model}}
  const c1=$('#c2s'),g1=c1.getContext('2d'),c2=$('#c2h');watch(c1,()=>draw());watch(c2,()=>draw());
  function drawSpectrum(){const r=fitCanvas(c1,g1);if(!r)return;const W=r.width,H=r.height,font=FONT();
    const pad={l:44,r:14,t:26,b:58},stripH=12;const yTop=pad.t,yBot=H-pad.b;
    const X=i=>pad.l+Math.log10(i)/lgn*(W-pad.l-pad.r),Y=v=>yBot-v*(yBot-yTop);
    g1.font=`500 11px ${font}`;g1.lineWidth=1;
    [0,.25,.5,.75,1].forEach(v=>{g1.strokeStyle=COL.grid;g1.beginPath();g1.moveTo(pad.l,Y(v));g1.lineTo(W-pad.r,Y(v));g1.stroke();g1.fillStyle=COL.muted;g1.textAlign='right';g1.textBaseline='middle';g1.fillText(String(v),pad.l-6,Y(v))});
    [1,10,100,1000,n].forEach(i=>{g1.strokeStyle=COL.grid;g1.beginPath();g1.moveTo(X(i),yTop);g1.lineTo(X(i),yBot);g1.stroke()});
    const kept=nKept(k);if(kept>=1){g1.strokeStyle=A(COL.navy,.7);g1.setLineDash([4,3]);g1.beginPath();g1.moveTo(X(Math.max(1,kept)),yTop);g1.lineTo(X(Math.max(1,kept)),yBot);g1.stroke();g1.setLineDash([]);
      g1.fillStyle=COL.navy;g1.textAlign='left';g1.textBaseline='top';g1.fillText('λ = a',X(Math.max(1,kept))+4,yTop+2)}
    const curve=(kk,col,w,dash)=>{g1.save();g1.strokeStyle=col;g1.lineWidth=w;if(dash)g1.setLineDash(dash);g1.beginPath();for(let i=0;i<n;i++){const x=X(i+1),y=Y(L[i]/(L[i]+kk));i?g1.lineTo(x,y):g1.moveTo(x,y)}g1.stroke();g1.restore()};
    curve(1,A(COL.muted,.9),1.2,[4,3]);curve(k,COL.navy,2.2);
    g1.fillStyle=COL.ink;g1.font=`600 12px ${font}`;g1.textAlign='left';g1.textBaseline='top';g1.fillText(`Keep share λ/(λ + a) of each of the ${n.toLocaleString('en-US')} directions, widest first`,pad.l,5);
    g1.font=`500 11px ${font}`;g1.fillStyle=COL.muted;g1.textAlign='right';g1.fillText('dashed: k = 1',W-pad.r,6);
    const sy1=yBot+8,sy2=sy1+stripH+4;const bx=b=>pad.l+b/NB*(W-pad.l-pad.r),bw=(W-pad.l-pad.r)/NB;const wmax=Math.max(...wb),emax=Math.max(...eb);
    for(let b=0;b<NB;b++){g1.fillStyle=A(COL.persona,.05+.9*wb[b]/wmax);g1.fillRect(bx(b),sy1,bw+.6,stripH);g1.fillStyle=A(COL.assist,.05+.9*eb[b]/emax);g1.fillRect(bx(b),sy2,bw+.6,stripH)}
    g1.font=`600 11px ${font}`;g1.textAlign='right';g1.textBaseline='middle';g1.fillStyle=COL.persona;g1.fillText('axis',pad.l-6,sy1+stripH/2);g1.fillStyle=COL.assist;g1.fillText('gap',pad.l-6,sy2+stripH/2);
    g1.font=`500 11px ${font}`;g1.fillStyle=COL.muted;g1.textAlign='center';g1.textBaseline='top';
    [1,10,100,1000,n].forEach(i=>g1.fillText(i.toLocaleString('en-US'),X(i),sy2+stripH+3));
    g1.textAlign='left';g1.fillText('direction rank (log)',pad.l,sy2+stripH+16)}
  function drawHolds(){loadCols();const v=view(sel);const series=[['ord',COL.persona,null],['push',COL.drift,[6,4]],['coh',COL.navy,[2,3]]].map(([key,col,dash])=>({
      pts:KS.map(kk=>{const x=v.at(kk,key);return[kk,x==null?null:(key==='coh'?x:100*x)]}),col,dash,w:2,marker:3.5}));
    lineChart(c2,{title:'Measured 20-turn holds with the persona prompt',x:{min:1,max:100,log:true,ticks:KS,label:'aperture k'},y:{min:0,max:100,ticks:[0,25,50,75,100]},series,vline:clamp(k,1,100)});
    const nearest=KS.reduce((a,b)=>Math.abs(Math.log(b/k))<Math.abs(Math.log(a/k))?b:a);
    const rv=(m)=>{const o=v.ref(m,'ord'),p=v.ref(m,'push'),c=v.ref(m,'coh');return o==null?'n/a':`${pct(o)} / ${pct(p)} / ${f0(c)}`};
    $('#c2note').textContent=`Same holds, same personas: prompt alone ${rv('none')}; vector ${rv('add')}; cap ${rv('cap')}; mean-shift control ${rv('meanshift_tok')} (in character / at pushes / coherence). Points are measured at k = 1, 3, 10, 30 and 100; the lines between them only guide the eye.`;
    return{nearest,v}}
  function draw(){loadCols();drawSpectrum();const h=drawHolds();if(!h)return;const{nearest,v}=h;const j=v.judges(nearest);
    reads('#m2',[[pct(1-keepAxis(k)),'pull along the persona axis per pass'],[nKept(k).toLocaleString('en-US'),'directions keeping more than half'],[pct(gapKept(k)),'share of the gap’s energy kept'],
      [`${pct(v.at(nearest,'ord'))} / ${pct(v.at(nearest,'push'))} / ${f0(v.at(nearest,'coh'))}`,`measured at k = ${nearest}: in character / pushes / coherence`+(j<4?` (${j} judges)`:'')]])}
  slider('r2k',x=>{const kk=kOf(x);return kk<10?kk.toFixed(1):kk.toFixed(0)},x=>{k=kOf(x);draw()});
  seg('#s2p',SEL,sel,v=>{sel=v;draw()});
})();

/* ================= what we ran: a better trigger ================= */
(function(){let gate='fisher',metric='mahal',pc=25;const probe={p:[0.8,-0.2]};
  const SW=W2.SigW,SWi=inv(SW),wF=mv(SWi,W2.d),wFu=unit(wF);
  const raw=h=>dot(h,W2.vhat),fis=h=>dot(h,wF);
  const rawP=W2.P.map(raw).sort((a,b)=>a-b),fisP=W2.P.map(fis).sort((a,b)=>a-b);
  const aucRaw=auroc(W2.Dr.map(raw),W2.P.map(raw)),aucFis=auroc(W2.Dr.map(fis),W2.P.map(fis));
  const pl=new Plot2D($('#c3'),BOX2,draw);pl.handles.push({get:()=>probe.p,set:w=>probe.p=w});
  const hc=$('#c3h'),hg=hc.getContext('2d');watch(hc,()=>draw());
  function hist(scoreP,scoreD,tau){const r=fitCanvas(hc,hg);if(!r)return;const W=r.width,H=r.height,pad={l:12,r:12,t:22,b:22};
    const all=scoreP.concat(scoreD);const lo=Math.min(...all),hi=Math.max(...all);const B=34,bw=(hi-lo)/B;
    const bins=a=>{const h=Array(B).fill(0);a.forEach(x=>h[Math.min(B-1,Math.floor((x-lo)/bw))]++);return h};
    const hp=bins(scoreP),hd=bins(scoreD);const mx=Math.max(...hp,...hd);
    const X=x=>pad.l+(x-lo)/(hi-lo)*(W-pad.l-pad.r),Y=v=>H-pad.b-v/mx*(H-pad.t-pad.b);
    [[hp,COL.persona],[hd,COL.drift]].forEach(([h,col])=>{hg.fillStyle=A(col,.35);hg.strokeStyle=col;hg.lineWidth=1.2;hg.beginPath();hg.moveTo(X(lo),Y(0));
      h.forEach((v,i)=>{hg.lineTo(X(lo+i*bw),Y(v));hg.lineTo(X(lo+(i+1)*bw),Y(v))});hg.lineTo(X(hi),Y(0));hg.closePath();hg.fill();hg.stroke()});
    hg.strokeStyle=gate==='fisher'?COL.violet:COL.navy;hg.lineWidth=2;hg.beginPath();hg.moveTo(X(tau),pad.t-6);hg.lineTo(X(tau),H-pad.b);hg.stroke();
    hg.font=`600 12px ${FONT()}`;hg.fillStyle=COL.ink;hg.textBaseline='top';hg.textAlign='left';
    hg.fillText((gate==='fisher'?'Fisher score w·h':'raw score v̂·h')+'   ← assistant-like   persona-like →',pad.l,4);
    hg.fillStyle=COL.muted;hg.textAlign='right';hg.fillText('floor',X(tau)-4,pad.t);hg.strokeStyle=COL.hair;hg.lineWidth=1;hg.beginPath();hg.moveTo(pad.l,H-pad.b);hg.lineTo(W-pad.r,H-pad.b);hg.stroke()}
  function draw(){if(!pl.ready())return;loadCols();pl.clear();
    const tr=quantile(rawP,pc/100),tf=quantile(fisP,pc/100);
    pl.halfplane(gate==='fisher'?wF:W2.vhat,gate==='fisher'?tf:tr,A(gate==='fisher'?COL.violet:COL.navy,.06));
    pl.boundary(W2.vhat,tr,COL.navy,1.6,[6,4],'raw floor');pl.boundary(wF,tf,COL.violet,2,null,'Fisher floor');
    drawAxis(pl);
    const trig=h=>gate==='fisher'?fis(h)<tf:raw(h)<tr;
    W2.A.forEach(p=>pl.dot(p,2.2,A(COL.assist,.22)));
    W2.P.forEach(p=>{const on=trig(p);pl.dot(p,2.6,A(COL.persona,.8),on?COL.ink:null,1.1)});
    W2.Dr.forEach(p=>{const on=trig(p);on?pl.dot(p,2.7,A(COL.drift,.85)):pl.dot(p,2.7,null,A(COL.drift,.85),1.2)});
    pl.arrow(W2.mP,add(W2.mP,scl(wFu,1.4)),COL.violet,2,8);pl.text(add(W2.mP,scl(wFu,1.65)),'w',COL.violet,{font:'700 13px',align:'center'});
    axisLabels(pl);const fp=fis(probe.p);pl.ring(probe.p);
    if(fp<tf){const delta=metric==='mahal'?scl(mv(SW,wF),(tf-fp)/dot(wF,mv(SW,wF))):scl(wF,(tf-fp)/dot(wF,wF));pl.arrow(probe.p,add(probe.p,delta),COL.edit,2.6,9)}
    const dM=h=>{if(fis(h)>=tf)return 0;const de=scl(mv(SW,wF),(tf-fis(h))/dot(wF,mv(SW,wF)));return Math.sqrt(dot(de,mv(SWi,de)))};
    const dE=h=>{if(fis(h)>=tf)return 0;const de=scl(wF,(tf-fis(h))/dot(wF,wF));return Math.sqrt(dot(de,mv(SWi,de)))};
    const cR=avg(W2.Dr.map(h=>raw(h)<tr?1:0)),cF=avg(W2.Dr.map(h=>fis(h)<tf?1:0));
    reads('#m3',[[pct(cR),'drifted caught, raw floor'],[pct(cF),'drifted caught, Fisher floor'],[f2(aucRaw)+' / '+f2(aucFis),'AUROC raw / Fisher'],
      [f2(dM(probe.p))+' / '+f2(dE(probe.p)),'probe edit in data units: data-metric / Euclidean']]);
    hist(gate==='fisher'?W2.P.map(fis):W2.P.map(raw),gate==='fisher'?W2.Dr.map(fis):W2.Dr.map(raw),gate==='fisher'?tf:tr)}
  seg('#s3g',[['raw','Gate: raw axis'],['fisher','Gate: Fisher']],gate,v=>{gate=v;draw()});
  seg('#s3m',[['mahal','Correction: data metric'],['euclid','Correction: Euclidean']],metric,v=>{metric=v;draw()});
  slider('r3p',v=>v+'%',v=>{pc=v;draw()});
})();

/* ================= what we ran: a region, in 3D ================= */
(function(){const r=mulberry32(5);const muP=[2,0,0],muA=[-2,0,0];const th=32*Math.PI/180;const u1=[Math.cos(th),Math.sin(th),0],u2=[-Math.sin(th),Math.cos(th),0];
  const tok=mu=>add(mu,add(add(scl(u1,1.15*randn(r)),scl(u2,.25*randn(r))),[0,0,.24*randn(r)]));
  const N=120,P=[],As=[],DA=[],DB=[];for(let i=0;i<N;i++){P.push(tok(muP));As.push(tok(muA))}
  for(let i=0;i<60;i++){DA.push(sub(tok(muP),[4*(.3+.5*r()),0,0]));DB.push(add(tok(muP),[0,0,.9+.9*r()]))}
  const mP=meanOf(P),mA3=meanOf(As),d3=sub(mP,mA3);const xs=P.map(p=>p[0]).sort((a,b)=>a-b);const tau=quantile(xs,.25);
  const SW3=mscl(madd(covOf(P),covOf(As)),.5),w3=mv(inv(SW3),d3),wd=dot(w3,d3);
  const coords=h=>[dot(w3,h),h[2]];const Q=P.map(coords);const qm=meanOf(Q);const S=covOf(Q),Si=inv(S),Sh=symFn(S,v=>Math.sqrt(Math.max(v,0)));
  const free=unit([-w3[1],w3[0],0]);
  const place=(base,q)=>{const h=add(base,scl(d3,(q[0]-dot(w3,base))/wd));h[2]=q[1];return h};
  let mode='region',rad=2.5;
  const edit=h=>{if(mode==='none')return{h,on:false};if(mode==='cap')return h[0]<tau?{h:[tau,h[1],h[2]],on:true}:{h,on:false};
    const q=sub(coords(h),qm);const m=Math.sqrt(dot(q,mv(Si,q)));if(m<=rad)return{h,on:false};return{h:place(h,add(qm,scl(q,rad/m))),on:true}};
  const pl=new Plot3D($('#c4'),draw,{yaw:-.38,pitch:.55,span:5});
  const ALL4=P.concat(As,DA,DB);
  function draw(){if(!pl.ready())return;loadCols();pl.clear();pl.fit(ALL4);pl.axes3([-4.6,-3.6,-1.6],1.2,['persona axis','content','identity']);
    if(mode==='cap'){const y0=-4,y1=4,z0=-1.6,z1=3.2;pl.poly([[tau,y0,z0],[tau,y1,z0],[tau,y1,z1],[tau,y0,z1]],A(COL.navy,.7),1.2,{close:true,fill:A(COL.navy,.07)})}
    if(mode==='region'){const ringAt=(s,t)=>place(add(mP,scl(free,s)),add(qm,mv(Sh,[rad*Math.cos(t),rad*Math.sin(t)])));
      for(const s of[-3.4,-1.7,0,1.7,3.4]){const ring=[];for(let i=0;i<=60;i++)ring.push(ringAt(s,i/60*2*Math.PI));pl.poly(ring,A(COL.navy,.55),1.1)}
      for(const t of[0,Math.PI/2,Math.PI,3*Math.PI/2])pl.poly([ringAt(-3.4,t),ringAt(3.4,t)],A(COL.navy,.4),1);
      pl.label(12,18,'navy cylinder: the region, unbounded along content',COL.navy)}
    if(mode==='cap')pl.label(12,18,'navy plane: the cap floor on the raw persona axis',COL.navy);
    const pts=[];As.forEach(p=>pts.push({p,r:2.1,fill:A(COL.assist,.3)}));P.forEach(p=>pts.push({p,r:2.6,fill:A(COL.persona,.8)}));
    DA.forEach(p=>pts.push({p,r:2.8,fill:A(COL.drift,.8)}));DB.forEach(p=>pts.push({p,r:2.8,fill:A(COL.paper,.9),stroke:COL.drift,lw:1.4}));pl.points(pts);
    let cA=0,cB=0,fp=0,dd=0;DA.forEach(h=>{const e=edit(h);if(e.on){cA++;pl.arrow(h,e.h,A(COL.edit,.6),1)}});DB.forEach(h=>{const e=edit(h);if(e.on){cB++;pl.arrow(h,e.h,A(COL.edit,.6),1)}});
    P.forEach(h=>{const e=edit(h);if(e.on){fp++;dd+=dot(sub(e.h,h),sub(e.h,h))}});const spread=Math.sqrt(avg(P.map(h=>dot(sub(h,mP),sub(h,mP)))));
    pl.text(add(muA,[0,0,-1.2]),'assistant',COL.assist);pl.text(add(mP,[0,0,-1.25]),'persona',COL.persona);
    reads('#m4',[[pct(cA/DA.length),'back-to-assistant drift edited (filled)'],[pct(cB/DB.length),'identity slips edited (hollow)'],[pct(fp/P.length),'in-character tokens edited'],[f2(Math.sqrt(dd/P.length)/spread),'distortion (in character)']])}
  seg('#s4',[['none','No steering'],['cap','Cap'],['region','Region']],mode,v=>{mode=v;draw()});
  slider('r4r',v=>(v/100).toFixed(2),v=>{rad=v/100;draw()});
  $('#b4v').addEventListener('click',()=>{pl.yaw=Math.atan2(free[0],free[1]);pl.pitch=0;draw()});
})();

/* ================= shared fits for the toy world ================= */
// Ridge logistic regression by Newton steps. Y = 1 for the class the classifier should flag.
function logistic(X,Y,lam=1){let th=[0,0,0];
  for(let it=0;it<30;it++){const g=[lam*th[0],lam*th[1],0];let H=[[lam,0,0],[0,lam,0],[0,0,1e-6]];
    X.forEach((x,i)=>{const xt=[x[0],x[1],1];const p=sigm(dot(th,xt));const e=p-Y[i],w=p*(1-p);
      for(let a=0;a<3;a++){g[a]+=e*xt[a];for(let b=0;b<3;b++)H[a][b]+=w*xt[a]*xt[b]}});
    th=sub(th,mv(inv(H),g))}
  return{w:[th[0],th[1]],b:th[2],p:h=>sigm(th[0]*h[0]+th[1]*h[1]+th[2])}}
const LOG_A=logistic(W2.P.concat(W2.A),W2.P.map(()=>0).concat(W2.A.map(()=>1)));   // flags assistant-like tokens
const FIS_W=mv(inv(W2.SigW),W2.d);

/* ================= how to move a token: the gallery ================= */
const MOVES=(function(){const d=W2.d,vh=W2.vhat,wFu=unit(FIS_W);
  const projP=W2.P.map(h=>dot(h,vh)).sort((a,b)=>a-b),fisP=W2.P.map(h=>dot(h,wFu)).sort((a,b)=>a-b);
  const SaH=symFn(W2.SigA,v=>Math.sqrt(Math.max(v,0))),SaHi=inv(SaH);
  const Amap=mm(mm(SaHi,symFn(mm(mm(SaH,W2.SigP),SaH),v=>Math.sqrt(Math.max(v,0)))),SaHi);
  const T=h=>add(W2.mP,mv(Amap,sub(h,W2.mA)));
  const target=unit(sub(W2.mP,ZERO));const I2=eye(2);let Ck=null,kC=-1;const getC=k=>{if(k!==kC){Ck=conceptor(W2.SigP,k);kC=k}return Ck};
  const pctP={label:'Floor: persona percentile',min:2,max:80,val:25,fmt:v=>v+'th'};
  const beta={label:'Strength β',min:0,max:100,val:100,fmt:v=>(v/100).toFixed(2)};
  const tpar={label:'Strength t',min:0,max:100,val:100,fmt:v=>(v/100).toFixed(2)};
  return[
    {id:'none',label:'None',param:null,eq:'h′ = h',desc:'No steering: the drifted tokens stay where they are.',src:'',f:h=>({h,on:false})},
    {id:'add',label:'Add',one:'v',param:{label:'Strength c',min:0,max:150,val:60,fmt:v=>(v/100).toFixed(2)},eq:'h′ = h + c·d',
      desc:'Adds the same vector to every token. The whole cloud shifts and keeps its shape, and tokens already in character get pushed past the persona.',
      src:`${cite('actadd','ActAdd')} (Turner et al. 2023), ${cite('caa','CAA')} (Panickssery et al. 2024), ${cite('pv','persona vectors')} (Chen et al. 2025). Our steering vector.`,
      f:(h,p)=>({h:add(h,scl(d,p/100)),on:p>0})},
    {id:'cap',label:'Clamp',one:'v',param:pctP,eq:'h′ = h + v̂ · max(0, τ − v̂·h)',
      desc:'Lifts only the tokens below a floor on one axis, to the floor. Everything above the floor is untouched.',
      src:`${cite('axis','Assistant Axis')} capping (Lu et al. 2026). Our cap.`,
      f:(h,p)=>{const t=quantile(projP,p/100),s=dot(h,vh);return s<t?{h:add(h,scl(vh,t-s)),on:true}:{h,on:false}}},
    {id:'band',label:'Band',one:'w',param:{label:'Band floor: persona percentile',min:2,max:60,val:25,fmt:v=>v+'th'},eq:'s = ŵ·h,   h′ = h + ŵ · (clip(s, τ_lo, τ_hi) − s)',
      desc:'Keeps a probe’s score inside an allowed band with the smallest possible move, so a token outside lands on the band’s edge. Here the probe is the Fisher direction and the band runs to the 99th percentile, so the chart below uses that axis.',
      src:`${cite('liseco','LiSeCo')} (Cheng & Amo Alonso 2024), which proves the probe score lands in the band at that layer.`,
      f:(h,p)=>{const lo=quantile(fisP,p/100),hi=quantile(fisP,.99),s=dot(h,wFu),c=clamp(s,lo,hi);return c!==s?{h:add(h,scl(wFu,c-s)),on:true}:{h,on:false}}},
    {id:'pin',label:'Pin',one:'v',param:beta,eq:'h′ = h − β · v̂ v̂ᵀ (h − μ_p)',
      desc:'Sets every token’s persona coordinate to the persona mean’s (the dashed teal line), from above and below. The cap is the one-sided version: it only lifts tokens below its floor.',
      src:'Shown for comparison; a two-sided clamp.',
      f:(h,p)=>{const s=dot(sub(h,W2.mP),vh);return{h:sub(h,scl(vh,p/100*s)),on:p>0}}},
    {id:'erase',label:'Erase',one:'v',param:beta,eq:'h′ = h − β · v̂ v̂ᵀ h        (h measured from the zero vector)',
      desc:'Sets the persona coordinate to zero, measured from the zero vector, so every token lands on the dashed navy line. Persona and assistant tokens then look the same along the axis: the move deletes the direction, so it can’t hold a persona along it. At strength β it multiplies the coordinate by 1 − β, which makes it Scale with the factor 1 − β.',
      src:`Directional ablation (${cite('arditi','Arditi et al. 2024')}). ${cite('leace','LEACE')} (Belrose et al. 2023) erases around the mean instead of zero, in closed form, so that no linear classifier can recover the concept.`,
      f:(h,p)=>{const s=dot(sub(h,ZERO),vh);return{h:sub(h,scl(vh,p/100*s)),on:p>0}}},
    {id:'scale',label:'Scale',one:'v',param:{label:'Scale β',min:0,max:300,val:200,fmt:v=>(v/100).toFixed(2)},eq:'h′ = h + (β − 1) · P_persona h        P_persona = v̂ v̂ᵀ here',
      desc:'Multiplies the persona coordinate by β, measured from the zero vector. β = 1 does nothing and β = 0 is Erase. With β above 1, tokens move away from the dashed navy line: tokens with some persona get more, and tokens on the assistant side get pushed further toward the assistant, so it only helps when the persona is already there.',
      src:`${cite('pass','PaSS')} (Malik & ElSherief 2026), with the persona subspace found by ${cite('inlp','INLP')} (Ravfogel et al. 2020).`,
      f:(h,p)=>{const s=dot(sub(h,ZERO),vh);return{h:add(h,scl(vh,(p/100-1)*s)),on:p!==100}}},
    {id:'shrink',label:'Shrink',param:{label:'Aperture k (× median)',min:0,max:200,val:100,fmt:v=>{const k=Math.pow(10,v/100);return k<10?k.toFixed(1):k.toFixed(0)}},eq:'h′ = h − (I − C)(h − μ_p)        C = R (R + aI)⁻¹,  a = k × median eigenvalue',
      desc:'Pulls each token toward the persona mean, by a/(λ + a) in each direction: hard where persona tokens barely vary, weakly where they vary a lot. The teal ellipse is what C keeps.',
      src:`Conceptors (${cite('jaeger','Jaeger 2014')}; ${cite('postmus','Postmus & Abreu 2024')}; ${cite('triant','Triantafyllopoulos et al. 2026')}). Our conceptor.`,
      f:(h,p)=>{const C=getC(Math.pow(10,p/100));return{h:sub(h,mv(msub(I2,C),sub(h,W2.mP))),on:true}}},
    {id:'mean',label:'Mean-shift',param:beta,eq:'h′ = h + β · (μ_p − h)',
      desc:'Pulls every token toward one point, so the cloud collapses. It is the conceptor’s limit at a very large aperture, and our control for it.',
      src:`Our matrix-removed control (after ${cite('razdan','Razdan & Balamurugan 2026')}).`,
      f:(h,p)=>({h:add(h,scl(sub(W2.mP,h),p/100)),on:p>0})},
    {id:'ot',label:'Transport',param:tpar,eq:'h′ = (1 − t)·h + t·(μ_p + A (h − μ_a))',
      desc:'Maps the assistant distribution onto the persona’s: it moves the mean and reshapes the spread. In-character tokens get moved too, unless a gate stops it.',
      src:`${cite('mimic','MiMiC')}, Gaussian optimal transport (Singh et al. 2024).`,
      f:(h,p)=>{const t=p/100;return{h:add(scl(h,1-t),scl(T(h),t)),on:t>0}}},
    {id:'rotate',label:'Rotate',param:tpar,eq:'h′ = |h| · slerp(ĥ, p̂; t)        p̂ = persona direction from the zero vector',
      desc:'Turns each token toward the persona direction by a fraction t of the angle and keeps its length. In 2D the fixed-plane and great-circle versions are the same turn. This toy flatters rotation: both clouds sit at about the same distance from the zero vector, so a turned token lands inside the persona cloud.',
      src:`${cite('spherical','Spherical steering')} (You et al. 2026), ${cite('angular','angular steering')} (Vu & Nguyen 2025), ${cite('hpr','Householder pseudo-rotation')} (Pham & Nguyen 2024).`,
      f:(h,p)=>{const t=p/100;const v=sub(h,ZERO),r=nrm(v);const a=Math.atan2(v[1],v[0]),b=Math.atan2(target[1],target[0]);let da=b-a;while(da>Math.PI)da-=2*Math.PI;while(da<-Math.PI)da+=2*Math.PI;
        const a2=a+t*da;return{h:add(ZERO,[r*Math.cos(a2),r*Math.sin(a2)]),on:t>0}}},
  ].map(o=>Object.assign(o,{getC,projP,fisP,wFu}))})();

/* ================= the same tokens in 3D ================= */
// Every 2D token keeps its x and y and gains a third coordinate z, a stand-in for the thousands of other directions:
// both clouds centre on z = 0, and the assistant spreads along it about twice as much as the persona.
const W3=(function(){const r=mulberry32(97);const P=W2.P.map(h=>[h[0],h[1],.65*randn(r)]),Ap=W2.A.map(h=>[h[0],h[1],1.3*randn(r)]),Dr=W2.Dr.map(h=>[h[0],h[1],.65*randn(r)]);
  const mP=meanOf(P),mA=meanOf(Ap),d=sub(mP,mA),SigP=covOf(P),SigA=covOf(Ap);
  return{P,A:Ap,Dr,mP,mA,d,vhat:unit(d),SigP,SigA,SigW:mscl(madd(SigP,SigA),.5),ZERO:[ZERO[0],ZERO[1],0]}})();
// one function per move, the 3D versions of MOVES; 'plane' rotation keeps z, as angular steering keeps everything off its plane
const MOVES3=(function(){const W=W3,Z3=W.ZERO,vh=W.vhat;const projP=W.P.map(h=>dot(h,vh)).sort((a,b)=>a-b);
  const wu=unit(mv(inv(W.SigW),W.d)),fisP=W.P.map(h=>dot(h,wu)).sort((a,b)=>a-b);
  const sq=M=>symFn(M,v=>Math.sqrt(Math.max(v,0))),SaH=sq(W.SigA),SaHi=inv(SaH),Amap=mm(mm(SaHi,sq(mm(mm(SaH,W.SigP),SaH))),SaHi);
  const T=h=>add(W.mP,mv(Amap,sub(h,W.mA)));const I3=eye(3);let Ck=null,kC=-1;const getC=k=>{if(k!==kC){Ck=conceptor(W.SigP,k);kC=k}return Ck};
  const pdir=unit(sub(W.mP,Z3));const st={rot:'sphere'};
  const F={none:h=>({h,on:false}),
    add:(h,p)=>({h:add(h,scl(W.d,p/100)),on:p>0}),
    cap:(h,p)=>{const t=quantile(projP,p/100),s=dot(h,vh);return s<t?{h:add(h,scl(vh,t-s)),on:true}:{h,on:false}},
    band:(h,p)=>{const lo=quantile(fisP,p/100),hi=quantile(fisP,.99),s=dot(h,wu),c=clamp(s,lo,hi);return c!==s?{h:add(h,scl(wu,c-s)),on:true}:{h,on:false}},
    pin:(h,p)=>{const s=dot(sub(h,W.mP),vh);return{h:sub(h,scl(vh,p/100*s)),on:p>0}},
    erase:(h,p)=>{const s=dot(sub(h,Z3),vh);return{h:sub(h,scl(vh,p/100*s)),on:p>0}},
    scale:(h,p)=>{const s=dot(sub(h,Z3),vh);return{h:add(h,scl(vh,(p/100-1)*s)),on:p!==100}},
    shrink:(h,p)=>{const C=getC(Math.pow(10,p/100));return{h:sub(h,mv(msub(I3,C),sub(h,W.mP))),on:true}},
    mean:(h,p)=>({h:add(h,scl(sub(W.mP,h),p/100)),on:p>0}),
    ot:(h,p)=>{const t=p/100;return{h:add(scl(h,1-t),scl(T(h),t)),on:t>0}},
    rotate:(h,p)=>{const t=p/100,v=sub(h,Z3),r=nrm(v);
      if(st.rot==='sphere')return{h:add(Z3,scl(slerpU(scl(v,1/r),pdir,t),r)),on:t>0};
      const a=Math.atan2(v[1],v[0]),b=Math.atan2(pdir[1],pdir[0]);let da=b-a;while(da>Math.PI)da-=2*Math.PI;while(da<-Math.PI)da+=2*Math.PI;
      const rr=Math.hypot(v[0],v[1]),a2=a+t*da;return{h:[Z3[0]+rr*Math.cos(a2),Z3[1]+rr*Math.sin(a2),h[2]],on:t>0}}};
  return{F,st,projP,fisP,wu,getC}})();

(function(){let op='add';const vals={};MOVES.forEach(o=>{if(o.param)vals[o.id]=o.param.val});
  const pl=new Plot2D($('#c_mv'),BOX2,draw);const rng=$('#r_mvp'),out=$('#o_mvp'),lbl=$('#lbl_mvp'),wrap=rng.closest('label');
  const cur=()=>MOVES.find(o=>o.id===op);
  // 3D twin: same move, same slider value, drawn on W3
  const pl3=new Plot3D($('#c_mv3'),()=>draw3(),{yaw:-.5,pitch:.42,span:5.4});const ALL3=W3.P.concat(W3.A,W3.Dr);
  const plane3=(n,tau,c0,col,label)=>{const o0=add(c0,scl(n,tau-dot(n,c0)));let e1=cross(n,[0,0,1]);if(nrm(e1)<1e-6)e1=[1,0,0];e1=unit(e1);const e2=cross(n,e1);
    const q=(a,b)=>add(o0,add(scl(e1,a),scl(e2,b)));pl3.poly([q(-3.6,-2.6),q(3.6,-2.6),q(3.6,2.6),q(-3.6,2.6)],A(col,.75),1.2,{close:true,fill:A(col,.06)});if(label)pl3.text(q(0,2.85),label,col,'600 11px')};
  function draw3(){if(!pl3.ready())return;loadCols();pl3.clear();const o=cur(),p=vals[o.id];const f=h=>MOVES3.F[o.id](h,p);const Z3=W3.ZERO,vh=W3.vhat;
    pl3.fit(ALL3);pl3.axes3([-5.4,-3.9,-2.6],1.1,['x','y','z']);const cen=scl(add(W3.mP,W3.mA),.5);
    if(o.id==='cap')plane3(vh,quantile(MOVES3.projP,p/100),cen,COL.navy,'floor');
    if(o.id==='band'){plane3(MOVES3.wu,quantile(MOVES3.fisP,p/100),cen,COL.violet,'band floor');plane3(MOVES3.wu,quantile(MOVES3.fisP,.99),cen,COL.violet,null)}
    if(o.id==='pin')plane3(vh,dot(vh,W3.mP),W3.mP,COL.persona,'persona mean’s coordinate');
    if(o.id==='erase'||o.id==='scale')plane3(vh,dot(vh,Z3),cen,COL.navy,'persona coordinate = 0');
    if(o.id==='shrink'){const C=MOVES3.getC(Math.pow(10,p/100));const{vals:ev,vecs}=symEig(C);pl3.ellipsoid(W3.mP,vecs,ev.map(v=>Math.max(v,.02)*2.1),A(COL.persona,.55))}
    if(o.id==='ot'){const{vals:ev,vecs}=symEig(W3.SigP);pl3.ellipsoid(W3.mP,vecs,ev.map(v=>2*Math.sqrt(Math.max(v,0))),A(COL.persona,.45))}
    if(o.id==='rotate'){const R=nrm(sub(W3.mP,Z3));[[1,0,0],[0,1,0],[0,0,1]].forEach((ax,i)=>{const u=[[0,1,0],[0,0,1],[1,0,0]][i],w=cross(ax,u);const ring=[];for(let j=0;j<=72;j++){const a=j/72*2*Math.PI;ring.push(add(Z3,add(scl(u,R*Math.cos(a)),scl(w,R*Math.sin(a)))))}pl3.poly(ring,A(COL.navy,.25),1,{dash:[3,4]})})}
    pl3.poly([sub(Z3,[.2,0,0]),add(Z3,[.2,0,0])],COL.ink,1.6);pl3.poly([sub(Z3,[0,.2,0]),add(Z3,[0,.2,0])],COL.ink,1.6);pl3.poly([sub(Z3,[0,0,.2]),add(Z3,[0,0,.2])],COL.ink,1.6);pl3.text(add(Z3,[0,0,-.4]),'zero vector',COL.muted,'500 11px');
    // same rule as the 2D drawMove: only drifted tokens move; in-character tokens a move shifts get a dark ring
    const eP=W3.P.map(f),eD=W3.Dr.map(f);const sh=(a,b)=>nrm(sub(a,b))/nrm(W3.d);const pts=[];
    W3.A.forEach(h=>pts.push({p:h,r:1.9,fill:A(COL.assist,.24)}));
    W3.P.forEach((h,i)=>{const s=sh(eP[i].h,h);pts.push({p:h,r:2.4,fill:A(COL.persona,.72),stroke:s>.01?A(COL.ink,.2+.45*Math.min(1,s/.3)):null,lw:1})});
    W3.Dr.forEach((h,i)=>{if(sh(eD[i].h,h)>.01)pts.push({p:h,r:2.1,fill:A(COL.drift,.16)})});
    eD.forEach(e=>pts.push({p:e.h,r:2.6,fill:A(COL.drift,.85)}));pl3.points(pts);
    eD.forEach((e,i)=>{if(i%4===0&&sh(e.h,W3.Dr[i])>.01)pl3.arrow(W3.Dr[i],e.h,A(COL.edit,.7),1.3,6)});
    pl3.text(add(W3.mA,[0,0,-1.25]),'assistant',COL.assist);pl3.text(add(W3.mP,[0,0,-1.25]),'persona',COL.persona);
    const sdz=a=>{const m=avg(a);return Math.sqrt(avg(a.map(x=>(x-m)**2)))};
    const zb=sdz(W3.Dr.map(h=>h[2])),za=sdz(eD.map(e=>e.h[2])),pb=sdz(W3.P.map(h=>h[2])),pa=sdz(eP.map(e=>e.h[2]));
    const lc=avg(eD.map((e,i)=>nrm(sub(e.h,Z3))/nrm(sub(W3.Dr[i],Z3))-1));
    reads('#m_mv3',[[f2(zb)+' → '+f2(za),'drifted tokens: spread along z'],[f2(pb)+' → '+f2(pa),'in-character tokens: spread along z'],[(lc>=0?'+':'')+(100*lc).toFixed(0)+'%','length change in 3D (drifted, from zero)']])}
  $('#b_mv3').addEventListener('click',()=>{pl3.yaw=0;pl3.pitch=-1.45;draw3()});
  seg('#s_mv3r',[['sphere','Great circle'],['plane','Fixed plane']],MOVES3.st.rot,v=>{MOVES3.st.rot=v;draw3()});
  function setOp(id){op=id;const o=cur();$('#s_mv3r').hidden=id!=='rotate';$('#d_mv').textContent=o.desc;$('#eq_mv').textContent=o.eq;$('#src_mv').innerHTML=o.src;
    if(o.param){wrap.hidden=false;lbl.textContent=o.param.label;rng.min=o.param.min;rng.max=o.param.max;rng.value=vals[o.id];out.textContent=o.param.fmt(vals[o.id])}else wrap.hidden=true;draw()}
  rng.addEventListener('input',()=>{const o=cur();if(!o.param)return;vals[o.id]=+rng.value;out.textContent=o.param.fmt(+rng.value);draw()});
  $('#k_mvf').addEventListener('change',()=>draw());
  // before/after chart: each token's coordinate along the move's axis, measured from the zero vector.
  // A one-axis move puts every token on one curve (its rule); a move that touches other directions scatters them.
  const rc=$('#c_mvr'),rg=rc.getContext('2d');watch(rc,()=>drawRule());
  function drawRule(){const r=fitCanvas(rc,rg);if(!r)return;loadCols();const o=cur(),p=vals[o.id];const W=r.width,H=r.height,font=FONT();
    const ax=o.one==='w'?unit(FIS_W):W2.vhat;const sOf=h=>dot(sub(h,ZERO),ax);
    const groups=[[W2.A,COL.assist,.3,1.8],[W2.P,COL.persona,.65,2.1],[W2.Dr,COL.drift,.75,2.1]];const pts=[];
    groups.forEach(([G,col,al,rad])=>G.forEach(h=>pts.push([sOf(h),sOf(o.f(h,p).h),A(col,al),rad])));
    // x spans the tokens' coordinates before; y spans before and after, so "no change" and the move both fit
    const span=(v,f=.06)=>{let a=Math.min(...v),b=Math.max(...v);const d=(b-a)*f||1;return[a-d,b+d]};
    const[x0,x1]=span(pts.map(q=>q[0])),[y0,y1]=span(pts.map(q=>q[0]).concat(pts.map(q=>q[1])));
    const pad={l:40,r:12,t:24,b:32};const X=v=>pad.l+(v-x0)/(x1-x0)*(W-pad.l-pad.r),Y=v=>H-pad.b-(v-y0)/(y1-y0)*(H-pad.t-pad.b);
    const step=s=>{const raw=s/6,e=Math.pow(10,Math.floor(Math.log10(raw))),m=raw/e;return(m<1.5?1:m<3.5?2:m<7.5?5:10)*e};
    rg.font=`500 11px ${font}`;rg.lineWidth=1;const sx=step(x1-x0),sy=step(y1-y0);
    for(let t=Math.ceil(x0/sx)*sx;t<=x1;t+=sx){rg.strokeStyle=COL.grid;rg.beginPath();rg.moveTo(X(t),pad.t);rg.lineTo(X(t),H-pad.b);rg.stroke();rg.fillStyle=COL.muted;rg.textAlign='center';rg.textBaseline='top';rg.fillText(String(+t.toFixed(2)),X(t),H-pad.b+4)}
    for(let t=Math.ceil(y0/sy)*sy;t<=y1;t+=sy){rg.strokeStyle=COL.grid;rg.beginPath();rg.moveTo(pad.l,Y(t));rg.lineTo(W-pad.r,Y(t));rg.stroke();rg.fillStyle=COL.muted;rg.textAlign='right';rg.textBaseline='middle';rg.fillText(String(+t.toFixed(2)),pad.l-6,Y(t))}
    rg.save();rg.beginPath();rg.rect(pad.l,pad.t,W-pad.l-pad.r,H-pad.t-pad.b);rg.clip();
    rg.save();rg.strokeStyle=A(COL.muted,.8);rg.setLineDash([4,4]);rg.beginPath();rg.moveTo(X(x0),Y(x0));rg.lineTo(X(x1),Y(x1));rg.stroke();rg.restore();
    if(x0<0&&x1>0){rg.save();rg.strokeStyle=A(COL.navy,.6);rg.setLineDash([2,3]);rg.beginPath();rg.moveTo(X(0),pad.t);rg.lineTo(X(0),H-pad.b);rg.stroke();rg.restore()}
    pts.forEach(q=>{rg.beginPath();rg.arc(X(q[0]),Y(q[1]),q[3],0,2*Math.PI);rg.fillStyle=q[2];rg.fill()});
    if(o.one){rg.strokeStyle=COL.edit;rg.lineWidth=2.2;rg.beginPath();for(let i=0;i<=160;i++){const s=x0+(x1-x0)*i/160;const s2=sOf(o.f(add(ZERO,scl(ax,s)),p).h);i?rg.lineTo(X(s),Y(s2)):rg.moveTo(X(s),Y(s2))}rg.stroke()}
    rg.restore();
    rg.fillStyle=COL.ink;rg.font=`600 12px ${font}`;rg.textAlign='left';rg.textBaseline='top';
    rg.fillText(o.one?`${o.label}: a one-axis rule`:`${o.label}: moves other coordinates too`,pad.l,5);
    rg.font=`500 11px ${font}`;rg.fillStyle=COL.muted;rg.textAlign='center';rg.textBaseline='bottom';
    rg.fillText((o.one==='w'?'Fisher score':'persona coordinate')+' before',pad.l+(W-pad.l-pad.r)/2,H-1);
    rg.save();rg.translate(12,pad.t+(H-pad.t-pad.b)/2);rg.rotate(-Math.PI/2);rg.textAlign='center';rg.textBaseline='middle';rg.fillText('after',0,0);rg.restore()}
  function draw(){drawRule();draw3();if(!pl.ready())return;loadCols();pl.clear();const o=cur();const p=vals[o.id];const edit=h=>o.f(h,p);
    if($('#k_mvf').checked){const st=.8,G=[];for(let x=BOX2.x0+.4;x<=BOX2.x1;x+=st)for(let y=BOX2.y0+.4;y<=BOX2.y1;y+=st)G.push([x,y]);
      const D=G.map(g=>sub(edit(g).h,g));const L=D.map(nrm).filter(x=>x>1e-6).sort((a,b)=>a-b);
      if(L.length){const q=quantile(L,.9),s=Math.min(1,.85*st/q);let clipped=0;
        G.forEach((g,i)=>{const n=nrm(D[i]);if(n<=1e-6)return;let len=s*n;if(len>1.1*st){len=1.1*st;clipped++}pl.arrow(g,add(g,scl(D[i],len/n)),A(COL.navy,.45),1,4)});
        pl.text([BOX2.x1-.15,BOX2.y1-.3],(s<1?`grid arrows at ${(100*s).toFixed(0)}% length`:'grid arrows at full length')+(clipped?', longest ones clipped':''),COL.muted,{align:'right'})}}
    if(o.id==='cap'){const t=quantile(o.projP,p/100);pl.halfplane(W2.vhat,t,A(COL.navy,.06));pl.boundary(W2.vhat,t,COL.navy,1.8,null,'floor')}
    if(o.id==='band'){const lo=quantile(o.fisP,p/100),hi=quantile(o.fisP,.99);pl.boundary(o.wFu,lo,COL.violet,1.8,null,'band floor');pl.boundary(o.wFu,hi,COL.violet,1.2,[5,4],'band ceiling')}
    if(o.id==='shrink'){const C=o.getC(Math.pow(10,p/100));const{vals:ev,vecs}=symEig(C);pl.ellipse(W2.mP,vecs,ev.map(v=>Math.max(v,.02)*2.1),COL.persona,{w:2,fill:A(COL.persona,.07)})}
    if(o.id==='rotate'){const R=nrm(sub(W2.mP,ZERO));pl.ellipse(ZERO,[[1,0],[0,1]],[R,R],A(COL.navy,.35),{w:1,dash:[3,4]})}
    if(o.id==='erase'||o.id==='scale')pl.boundary(W2.vhat,dot(W2.vhat,ZERO),COL.navy,1.6,[6,4],'persona coordinate = 0');
    if(o.id==='pin')pl.boundary(W2.vhat,dot(W2.vhat,W2.mP),COL.persona,1.6,[6,4],'persona mean’s coordinate');
    pl.line(sub(ZERO,[.18,0]),add(ZERO,[.18,0]),COL.ink,1.6);pl.line(sub(ZERO,[0,.18]),add(ZERO,[0,.18]),COL.ink,1.6);pl.text(add(ZERO,[.28,.02]),'zero vector',COL.muted);
    drawAxis(pl);const m=metrics(edit);drawMove(pl,m);
    reads('#m_mv',[[pct(m.restore),'restore (drifted)'],[f2(m.dist),'distortion (in character)'],[(m.normCh>=0?'+':'')+(100*m.normCh).toFixed(0)+'%','length change (drifted, from zero)'],[pct(m.landed),'drifted tokens landing in the persona’s 2σ ellipse']])}
  seg('#s_mv',MOVES.map(o=>[o.id,o.label]),op,v=>setOp(v));
  const tb=$('#t_ops');tb.innerHTML='<thead><tr><th>Move</th><th>Formula</th><th>What it does</th><th>Source</th></tr></thead><tbody>'+
    MOVES.filter(o=>o.id!=='none').map(o=>`<tr><td><b>${o.label}</b></td><td><code>${o.eq.replace(/</g,'&lt;')}</code></td><td>${o.desc}</td><td>${o.src}</td></tr>`).join('')+'</tbody>';
  setOp(op);
})();

/* ================= when to act: gates ================= */
(function(){const d=W2.d,vh=W2.vhat;
  const rawP=W2.P.map(h=>dot(h,vh)).sort((a,b)=>a-b),fisP=W2.P.map(h=>dot(h,FIS_W)).sort((a,b)=>a-b);
  // GAPS: a neuron basis that is not aligned with d, per-neuron AUROC and 1D Gaussians for each class
  const ang=35*Math.PI/180,NB=[[Math.cos(ang),Math.sin(ang)],[-Math.sin(ang),Math.cos(ang)]];
  const nstat=NB.map(e=>{const a=W2.A.map(h=>dot(h,e)),p=W2.P.map(h=>dot(h,e));const ma=avg(a),mp=avg(p);
    const va=avg(a.map(x=>(x-ma)**2)),vp=avg(p.map(x=>(x-mp)**2));return{e,auc:auroc(p,a),ma,mp,va,vp}});
  const postA=(s,x)=>{const la=-.5*(x-s.ma)**2/s.va-.5*Math.log(s.va),lp=-.5*(x-s.mp)**2/s.vp-.5*Math.log(s.vp);return sigm(la-lp)};
  let gate='fisher',c=+$('#r_gtc').value/100;const tv={raw:25,fisher:25,dsas:100,gaps:30};
  const G=[
    {id:'always',label:'Always on',param:null,eq:'g(h) = 1',desc:'Every token gets the full move. This is the steering vector.',src:`${cite('actadd','ActAdd')}, ${cite('caa','CAA')}.`},
    {id:'raw',label:'Raw floor',param:{label:'Floor: persona percentile',min:2,max:60,fmt:v=>v+'th'},eq:'g(h) = 1  if  v̂·h < τ',desc:'The cap’s trigger: a token below a percentile of in-character tokens on the raw axis gets the move.',src:`${cite('axis','Assistant Axis')} capping (Lu et al. 2026).`},
    {id:'fisher',label:'Fisher floor',param:{label:'Floor: persona percentile',min:2,max:60,fmt:v=>v+'th'},eq:'g(h) = 1  if  w·h < τ_w,   w = Σ_W⁻¹ d',desc:'The same floor on the Fisher score, which discounts content. This is fisher_cap’s trigger.',src:'Our proposal (fisher_cap, Appendix B).'},
    {id:'near',label:'Nearer the assistant',param:null,eq:'g(h) = 1  if  |h − μ_a| < |h − μ_p|',desc:'Moves only tokens closer to the assistant mean than to the persona mean. MiMiC applies its transport map with this rule.',src:`${cite('mimic','MiMiC')} (Singh et al. 2024).`},
    {id:'dsas',label:'Learned soft gate',param:{label:'Gate temperature',min:20,max:300,fmt:v=>(v/100).toFixed(2)},eq:'g(h) = σ((wᵀh + b) / T),   h′ = (1 − g)·h + g·(h + c·d)',desc:'A logistic classifier, trained to tell assistant tokens from persona tokens, gives each token a weight between 0 and 1, and the edit blends the original and steered states by it.',src:`${cite('dsas','DSAS')} (Ferrando et al. 2025), which trains a per-layer logistic gate and wraps any steering map.`},
    {id:'gaps',label:'Per-neuron masks',param:{label:'Separability threshold |AUROC − ½|',min:0,max:48,fmt:v=>(v/100).toFixed(2)},eq:'h′ = h + c · (m_sep ⊙ m_post(h)) ⊙ d',desc:'Keeps neurons whose values separate the two classes, and per token steers only the neurons whose current value looks like the assistant’s under a per-neuron Gaussian. The gray dashed lines are the two neuron axes.',src:`${cite('gaps','GAPS')} (Fereidouni et al. 2026), which adds these masks to a ${cite('cast','CAST')} or DSAS gate.`},
  ];
  const cur=()=>G.find(o=>o.id===gate);
  function gateOf(h){const o=cur();if(o.id==='always')return{g:1,v:d};
    if(o.id==='raw'){const t=quantile(rawP,tv.raw/100);return{g:dot(h,vh)<t?1:0,v:d}}
    if(o.id==='fisher'){const t=quantile(fisP,tv.fisher/100);return{g:dot(h,FIS_W)<t?1:0,v:d}}
    if(o.id==='near'){return{g:nrm(sub(h,W2.mA))<nrm(sub(h,W2.mP))?1:0,v:d}}
    if(o.id==='dsas'){const T=tv.dsas/100;const z=LOG_A.w[0]*h[0]+LOG_A.w[1]*h[1]+LOG_A.b;return{g:sigm(z/T),v:d}}
    const thr=tv.gaps/100;let v=[0,0],k=0;nstat.forEach(s=>{if(Math.abs(s.auc-.5)>thr&&postA(s,dot(h,s.e))>.5){v=add(v,scl(s.e,dot(d,s.e)));k++}});
    return{g:nrm(v)/nrm(d),v:nrm(v)>0?scl(unit(v),nrm(d)):d}}
  const pl=new Plot2D($('#c_gt'),BOX2,draw);const rng=$('#r_gtt'),out=$('#o_gtt'),lbl=$('#lbl_gtt'),wrap=$('#w_gtt');
  function setGate(id){gate=id;const o=cur();$('#d_gt').textContent=o.desc;$('#eq_gt').textContent=o.eq;$('#src_gt').innerHTML=o.src;
    if(o.param){wrap.hidden=false;lbl.textContent=o.param.label;rng.min=o.param.min;rng.max=o.param.max;rng.value=tv[o.id];out.textContent=o.param.fmt(tv[o.id])}else wrap.hidden=true;draw()}
  rng.addEventListener('input',()=>{const o=cur();if(!o.param)return;tv[o.id]=+rng.value;out.textContent=o.param.fmt(+rng.value);draw()});
  slider('r_gtc',v=>(v/100).toFixed(2),v=>{c=v/100;draw()});
  function edit(h){const{g,v}=gateOf(h);if(gate==='gaps'){const vv=scl(v,c*g);return{h:add(h,vv),on:g>.02,g}}return{h:add(h,scl(v,c*g)),on:g>.02,g}}
  function draw(){if(!pl.ready())return;loadCols();pl.clear();const o=cur();
    if(o.id==='raw'){const t=quantile(rawP,tv.raw/100);pl.halfplane(vh,t,A(COL.navy,.06));pl.boundary(vh,t,COL.navy,1.8,null,'raw floor')}
    if(o.id==='fisher'){const t=quantile(fisP,tv.fisher/100);pl.halfplane(FIS_W,t,A(COL.violet,.06));pl.boundary(FIS_W,t,COL.violet,1.8,null,'Fisher floor')}
    if(o.id==='near'){const n=sub(W2.mP,W2.mA),t=dot(n,scl(add(W2.mP,W2.mA),.5));pl.halfplane(n,t,A(COL.navy,.06));pl.boundary(n,t,COL.navy,1.6,[5,4],'equal distance')}
    if(o.id==='dsas'){const n=scl(LOG_A.w,-1);pl.boundary(n,LOG_A.b,COL.navy,1.6,[5,4],'g = ½')}
    if(o.id==='gaps'){nstat.forEach((s,i)=>{pl.line(scl(s.e,-7),scl(s.e,7),A(COL.muted,.6),1,[4,4]);pl.text(scl(s.e,i?2.9:4.6),`neuron ${i+1}`+(Math.abs(s.auc-.5)>tv.gaps/100?'':' (masked)'),COL.muted)})}
    drawAxis(pl);const m=metrics(h=>edit(h)),eP=m.Pe,eD=m.De;drawMove(pl,m,{every:2});
    reads('#m_gt',[[pct(avg(eD.map(e=>e.g))),'mean gate on drifted tokens'],[pct(avg(eP.map(e=>e.g))),'mean gate on in-character tokens'],[pct(m.restore),'restore (drifted)'],[f2(m.dist),'distortion (in character)']])}
  seg('#s_gt',G.map(o=>[o.id,o.label]),gate,v=>setGate(v));
  setGate(gate);
})();

/* ================= which directions to fit ================= */
(function(){// estimators are fit on a larger draw from the same toy world, so sampling noise doesn't steer the picture
  const WB=makeWorld2D(11,1200),d=WB.d,mG=scl(add(W2.mP,W2.mA),.5),mGB=scl(add(WB.mP,WB.mA),.5);let est='mean',rr=1;
  const orient=v=>dot(v,d)<0?scl(v,-1):v;
  const LOG_P=logistic(WB.P.concat(WB.A),WB.P.map(()=>1).concat(WB.A.map(()=>0)));
  const FIS_B=mv(inv(WB.SigW),d),PAIR_B=symEig(momentAbout(WB.D,[0,0])).vecs[0],PCA_B=symEig(covOf(WB.P.concat(WB.A))).vecs[0];
  const SpB=momentAbout(WB.P,mGB),SaB=momentAbout(WB.A,mGB);
  const ccs=r=>{const{vecs}=symEig(msub(SpB,mscl(SaB,r)));const u=vecs[0];const v=scl(u,dot(u,sub(WB.mP,mGB)));return orient(nrm(v)>1e-9?v:u)};
  const E=[
    {id:'mean',label:'Mean difference',col:'navy',v:()=>d,eq:'d = μ_p − μ_a',desc:'The arrow from the assistant’s average token to the persona’s average token. Our vector, cap and region use it, and so do persona vectors. Any content that differs between the two clouds tilts it.',src:`${cite('caa','CAA')} (Panickssery et al. 2024); ${cite('pv','persona vectors')} (Chen et al. 2025).`},
    {id:'fisher',label:'Fisher',col:'violet',v:()=>FIS_B,eq:'w = Σ_W⁻¹ d',desc:'The mean difference, corrected for how much tokens spread in each direction. Directions where tokens vary a lot anyway, like content, count for less, so the arrow turns away from content. If both clouds are Gaussian with the same spread, this is the best possible line for telling them apart.',src:'Fisher’s linear discriminant, a textbook method. Our fisher_cap uses it as its trigger.'},
    {id:'probe',label:'Probe (INLP step)',col:'ochre',v:()=>LOG_P.w,eq:'w = logistic regression weights (persona vs assistant)',desc:'Train a classifier to tell persona tokens from assistant tokens and use its weights as the direction. INLP repeats this: remove the direction, train again, and stop when no classifier works. PaSS treats all the removed directions as the persona subspace.',src:`${cite('inlp','INLP')} (Ravfogel et al. 2020); ${cite('pass','PaSS')} (Malik & ElSherief 2026).`},
    {id:'paired',label:'Paired differences',col:'edit',v:()=>PAIR_B,eq:'top eigenvector of  E[(p_i − a_i)(p_i − a_i)ᵀ]',desc:'Pair each persona token with an assistant token about the same content and subtract. The content cancels in each difference, so what’s left is the persona. Our diffpull is fit on these differences.',src:'Our diffpull (per-question differences).'},
    {id:'ccs',label:'Covariance contrast',col:'persona',v:()=>ccs(rr),eq:'leading eigenvector u of  S_p − r·S_a   (scatter about the grand mean)\nv = u uᵀ (μ_p − μ_G)',desc:'Compare how the two clouds spread instead of where their centres sit: keep the directions where persona tokens spread more than assistant tokens do. With r near 1, the content both clouds share cancels and the persona’s style direction wins. In real models its strength is removing many nuisance classes at once, which 2D can’t show.',src:`${cite('ccs','Contrastive covariance subspaces')} (Xenos et al. 2026).`},
    {id:'pca',label:'PCA, no labels',col:'muted',v:()=>PCA_B,eq:'top eigenvector of the pooled covariance',desc:'The direction along which all tokens together vary most, found without knowing which token is which. Here it still finds the persona offset, but it leans toward content.',src:'Baseline, no labels.'},
  ];
  const pl=new Plot2D($('#c_dir'),BOX2,draw);const wrap=$('#w_dirr');
  slider('r_dirr',v=>(v/100).toFixed(2),v=>{rr=v/100;draw()});
  function setEst(id){est=id;const o=E.find(x=>x.id===id);$('#d_dir').textContent=o.desc;$('#eq_dir').textContent=o.eq;$('#src_dir').innerHTML=o.src;wrap.hidden=id!=='ccs';draw()}
  function draw(){if(!pl.ready())return;loadCols();pl.clear();
    pl.line(sub(mG,scl(W2.u1,6)),add(mG,scl(W2.u1,6)),A(COL.muted,.7),1.2,[2,4]);pl.text(add(mG,scl(W2.u1,3.6)),'content',COL.muted);
    pl.line(sub(W2.mP,scl(W2.w1,1.6)),add(W2.mP,scl(W2.w1,1.6)),A(COL.persona,.7),1.2,[2,4]);pl.text(add(W2.mP,scl(W2.w1,1.95)),'persona style',COL.persona);
    drawClouds(pl,{drift:false,af:.3});pl.dot(W2.mA,4.5,COL.assist,COL.paper,1.5);pl.dot(W2.mP,4.5,COL.persona,COL.paper,1.5);
    E.forEach(o=>{const v=unit(orient(o.v()));const on=o.id===est;pl.arrow(mG,add(mG,scl(v,on?2.6:2.1)),on?COL[o.col]:A(COL[o.col],.35),on?2.8:1.4,on?10:6);
      if(on)pl.text(add(mG,scl(v,2.95)),o.label,COL[o.col],{align:'center',font:'600 12px'})});
    const o=E.find(x=>x.id===est);const v=unit(orient(o.v()));
    const pp=W2.P.map(h=>dot(h,v)),pa=W2.A.map(h=>dot(h,v));const ang=Math.acos(clamp(dot(v,unit(d)),-1,1))*180/Math.PI;
    const totP=W2.SigP[0][0]+W2.SigP[1][1];const along=dot(v,mv(W2.SigP,v))/totP;
    reads('#m_dir',[[ang.toFixed(0)+'°','angle to the mean difference'],[f2(Math.abs(dot(v,W2.u1))),'|cos| with the content direction'],[f2(auroc(pa,pp)),'AUROC, persona vs assistant'],[pct(along),'share of persona-token spread along it']])}
  seg('#s_dir',E.map(o=>[o.id,o.label]),est,v=>setEst(v));
  setEst(est);
})();

/* ================= moving distributions: transport ================= */
(function(){let mode='ot',t=1,sharp=1;const SaH=symFn(W2.SigA,v=>Math.sqrt(Math.max(v,0))),SaHi=inv(SaH);
  const Amap=mm(mm(SaHi,symFn(mm(mm(SaH,W2.SigP),SaH),v=>Math.sqrt(Math.max(v,0)))),SaHi);
  const T=h=>add(W2.mP,mv(Amap,sub(h,W2.mA)));
  const SPi=inv(W2.SigP),SAi=inv(W2.SigA);const ldP=Math.log(W2.SigP[0][0]*W2.SigP[1][1]-W2.SigP[0][1]**2),ldA=Math.log(W2.SigA[0][0]*W2.SigA[1][1]-W2.SigA[0][1]**2);
  const llr=h=>{const a=sub(h,W2.mP),b=sub(h,W2.mA);return -.5*dot(a,mv(SPi,a))-.5*ldP+.5*dot(b,mv(SAi,b))+.5*ldA};
  const piA=h=>sigm(-llr(h)*sharp/4);
  const sqrtm=M=>symFn(M,v=>Math.sqrt(Math.max(v,0)));
  const w2=(m1,S1,m2,S2)=>{const S2h=sqrtm(S2);const X=sqrtm(mm(mm(S2h,S1),S2h));const tr=M=>M[0][0]+M[1][1];return Math.sqrt(Math.max(0,dot(sub(m1,m2),sub(m1,m2))+tr(S1)+tr(S2)-2*tr(X)))};
  const pl=new Plot2D($('#c5'),BOX2,draw);let anim=null;
  function draw(){if(!pl.ready())return;loadCols();pl.clear();drawAxis(pl);
    // gated: the tokens of a persona conversation (in character and drifted) get the map in proportion to how
    // assistant-like they look; the assistant cloud is only the reference the map was fit on, so it stays still
    if(mode==='gated'){const ed=h=>{const g=piA(h);return{h:add(h,scl(sub(T(h),h),g)),on:g>.02,g}};
      const m=metrics(ed);drawMove(pl,m);
      reads('#m5',[[pct(m.restore),'restore (drifted)'],[f2(m.dist),'distortion (in character)'],[pct(avg(m.De.map(e=>e.g))),'mean gate on drifted tokens'],[pct(avg(m.Pe.map(e=>e.g))),'mean gate on in-character tokens']])}
    else{W2.P.forEach(p=>pl.dot(p,2.4,A(COL.persona,.35)));pl.covEllipse(W2.mP,W2.SigP,2,COL.persona,{w:2,dash:[5,4]});
      const moved=W2.A.map(h=>mode==='ot'?add(scl(h,1-t),scl(T(h),t)):add(h,scl(W2.d,t)));
      moved.forEach(p=>pl.dot(p,2.6,A(COL.assist,.75)));const mm_=meanOf(moved),Sm=covOf(moved);pl.covEllipse(mm_,Sm,2,COL.edit,{w:2.2});
      for(let i=0;i<W2.A.length;i+=6)pl.line(W2.A[i],moved[i],A(COL.edit,.25),1);
      const shapeErr=w2([0,0],Sm,[0,0],W2.SigP);axisLabels(pl);
      reads('#m5',[[f2(w2(mm_,Sm,W2.mP,W2.SigP)),'distance to persona cloud (W₂)'],[f2(shapeErr),'shape mismatch alone (W₂, means aligned)'],[f2(t),'progress t'],[mode==='ot'?'shift + reshape':'shift only','what moves']])}}
  seg('#s5',[['vector','Shift (vector)'],['ot','Transport'],['gated','Gated transport']],mode,v=>{mode=v;draw()});
  slider('r5t',v=>(v/100).toFixed(2),v=>{t=v/100;draw()});slider('r5g',v=>(v/100).toFixed(2),v=>{sharp=v/100;draw()});
  $('#b5p').addEventListener('click',()=>{if(anim){cancelAnimationFrame(anim);anim=null;return}const el=$('#r5t');const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(reduce){el.value=100;t=1;$('#o5t').textContent='1.00';draw();return}let v=0;const step=()=>{v=Math.min(100,v+1.4);el.value=v;t=v/100;$('#o5t').textContent=t.toFixed(2);draw();anim=v<100?requestAnimationFrame(step):null};step()});
})();

/* ================= curved geometry: flat and curved, in general ================= */
// A sheet bent into part of a cylinder. u runs along the bend, v along the straight edge. The geodesic between two
// points is a straight line in (u, v), wrapped onto the sheet, so its length never changes as the sheet bends.
(function(){let bend=.8,t=.5;const Lu=6,Ly=3,N=280,sig=.05;const rnd=mulberry32(61);
  const UV=[];for(let i=0;i<N;i++)UV.push([2*rnd()-1,2*rnd()-1,randn(rnd)]);const Aq=[-.85,-.55],Bq=[.85,.55];
  const geom=()=>{const ph=Math.max(1e-4,bend*Math.PI),R=Lu/ph,zc=R*(1-Math.cos(ph/2))/2;
    const at=(u,v,n=0)=>{const th=u*Lu/2/R;return[R*Math.sin(th)+n*Math.sin(th),v*Ly/2,R*(1-Math.cos(th))-zc-n*Math.cos(th)]};return{at,R}};
  const pl3=new Plot3D($('#c_fc3'),draw,{yaw:-.55,pitch:.38,span:3.4});const pl2=new Plot2D($('#c_fc2'),{x0:-3.4,x1:3.4,y0:-1.7,y1:1.7},draw);
  // the box every bend fits in (flat: x ±3; fully bent: z ±1), so the 3D zoom holds while the bend changes
  const FCB=[];for(const x of[-3,3])for(const y of[-1.5,1.5])for(const z of[-1,1])FCB.push([x,y,z]);
  function draw(){loadCols();const G=geom();const a=G.at(...Aq),b=G.at(...Bq);
    const chord=Array.from({length:41},(_,i)=>add(a,scl(sub(b,a),i/40)));const geo=Array.from({length:41},(_,i)=>{const s=i/40;return G.at(Aq[0]+(Bq[0]-Aq[0])*s,Aq[1]+(Bq[1]-Aq[1])*s)});
    const grid=[];for(let i=0;i<=120;i++)for(let j=0;j<=24;j++)grid.push(G.at(-1+i/60,-1+j/12));
    const gapOf=q=>Math.min(...grid.map(g=>nrm(sub(g,q))));const gaps=chord.map(gapOf);
    const dS=nrm(sub(b,a)),dG=Math.hypot((Bq[0]-Aq[0])*Lu/2,(Bq[1]-Aq[1])*Ly/2);
    const ms=add(a,scl(sub(b,a),t)),mg=G.at(Aq[0]+(Bq[0]-Aq[0])*t,Aq[1]+(Bq[1]-Aq[1])*t);
    if(pl3.ready()){pl3.clear();pl3.fit(FCB);pl3.axes3([-3.1,-2.4,-1.9],.8,['x','y','z']);
      for(let i=0;i<=12;i++){const u=-1+i/6;pl3.poly(Array.from({length:13},(_,j)=>G.at(u,-1+j/6)),A(COL.navy,.18),1)}
      for(let j=0;j<=4;j++){const v=-1+j/2;pl3.poly(Array.from({length:61},(_,i)=>G.at(-1+i/30,v)),A(COL.navy,.18),1)}
      pl3.points(UV.map(([u,v,n])=>({p:G.at(u,v,sig*n),r:1.9,fill:A(COL.persona,.55)})));
      pl3.poly(chord,COL.edit,2.2,{dash:[6,4]});pl3.poly(geo,COL.navy,2.4);
      pl3.points([{p:a,r:6,fill:COL.ochre,stroke:COL.paper,lw:1.5},{p:b,r:6,fill:COL.violet,stroke:COL.paper,lw:1.5},{p:ms,r:5,fill:COL.paper,stroke:COL.edit,lw:2.2},{p:mg,r:5,fill:COL.paper,stroke:COL.navy,lw:2.2}])}
    if(pl2.ready()){pl2.clear();const P2=q=>[q[0],q[2]];
      UV.forEach(([u,v,n])=>pl2.dot(P2(G.at(u,v,sig*n)),2.1,A(COL.persona,.45)));
      pl2.path(Array.from({length:61},(_,i)=>P2(G.at(-1+i/30,0))),A(COL.navy,.35),1);
      pl2.path(chord.map(P2),COL.edit,2,[6,4]);pl2.path(geo.map(P2),COL.navy,2.4);
      pl2.dot(P2(a),6,COL.ochre,COL.paper,1.5);pl2.dot(P2(b),6,COL.violet,COL.paper,1.5);pl2.dot(P2(ms),5,COL.paper,COL.edit,2.2);pl2.dot(P2(mg),5,COL.paper,COL.navy,2.2);
      pl2.text([-3.25,1.5],'end-on: x across, z up',COL.muted)}
    reads('#m_fc',[[f2(dS),'straight-line distance'],[f2(dG),'distance along the sheet (never changes)'],[f2(dG/dS),'ratio: along the sheet / straight'],[f2(Math.max(...gaps)),'largest gap between the straight path and the sheet']])}
  slider('r_fcb',v=>(v/100).toFixed(2),v=>{bend=v/100;draw()});slider('r_fct',v=>(v/100).toFixed(2),v=>{t=v/100;draw()});
})();

/* ================= curved geometry: straight lines leave curved data ================= */
(function(){let bend=.7,t=.5;const N=170,sig=.12;const BOXM={x0:-5,x1:5,y0:-3.6,y1:3.6};
  const pl=new Plot2D($('#c_mf'),BOXM,draw);let S=null;
  function build(){const r=mulberry32(31);const phi=Math.max(.03,bend*1.5*Math.PI),R=8.2/phi;
    const raw=[];for(let i=0;i<N;i++){const th=-phi/2+phi*(i+.5)/N+(r()-.5)*phi/N;const rr=R+sig*randn(r);raw.push([rr*Math.sin(th),rr*Math.cos(th)])}
    const ends=[[R*Math.sin(-phi/2),R*Math.cos(-phi/2)],[R*Math.sin(phi/2),R*Math.cos(phi/2)]];
    const all=raw.concat(ends);const x0=Math.min(...all.map(p=>p[0])),x1=Math.max(...all.map(p=>p[0])),y0=Math.min(...all.map(p=>p[1])),y1=Math.max(...all.map(p=>p[1]));
    const c=[(x0+x1)/2,(y0+y1)/2];const pts=raw.map(p=>sub(p,c)),a=sub(ends[0],c),b=sub(ends[1],c);
    const V=pts.concat([a,b]);const n=V.length,K=8;const adj=V.map(()=>[]);
    for(let i=0;i<n;i++){V.map((q,j)=>[j,nrm(sub(q,V[i]))]).filter(x=>x[0]!==i).sort((u,v)=>u[1]-v[1]).slice(0,K).forEach(([j,w])=>{adj[i].push([j,w]);adj[j].push([i,w])})}
    const dist=Array(n).fill(Infinity),prev=Array(n).fill(-1),done=Array(n).fill(false);dist[n-2]=0;
    for(let it=0;it<n;it++){let u=-1;for(let i=0;i<n;i++)if(!done[i]&&(u<0||dist[i]<dist[u]))u=i;if(u<0||dist[u]===Infinity)break;done[u]=true;if(u===n-1)break;
      adj[u].forEach(([j,w])=>{if(dist[u]+w<dist[j]){dist[j]=dist[u]+w;prev[j]=u}})}
    let geo=[];if(dist[n-1]<Infinity){for(let v=n-1;v>=0;v=prev[v]){geo.push(V[v]);if(v===n-2)break}geo.reverse()}else geo=[a,b];
    S={pts,a,b,geo,dg:dist[n-1]<Infinity?dist[n-1]:nrm(sub(b,a)),de:nrm(sub(b,a))}}
  const lenOf=path=>{let L=0;for(let i=1;i<path.length;i++)L+=nrm(sub(path[i],path[i-1]));return L};
  const at=(path,f)=>{const L=lenOf(path)*f;let acc=0;for(let i=1;i<path.length;i++){const s=nrm(sub(path[i],path[i-1]));if(acc+s>=L)return add(path[i-1],scl(sub(path[i],path[i-1]),(L-acc)/Math.max(s,1e-9)));acc+=s}return path[path.length-1]};
  const gap=p=>Math.min(...S.pts.map(q=>nrm(sub(q,p))))/sig;
  function draw(){if(!pl.ready())return;loadCols();if(!S)build();pl.clear();
    S.pts.forEach(p=>pl.dot(p,2.4,A(COL.persona,.55)));
    const straight=[S.a,S.b];pl.path(straight,COL.edit,2,[6,4]);pl.path(S.geo,COL.navy,2.4);
    const ms=at(straight,t),mg=at(S.geo,t);pl.dot(ms,6,A(COL.paper,.9),COL.edit,2.2);pl.dot(mg,6,A(COL.paper,.9),COL.navy,2.2);
    pl.dot(S.a,6,COL.ochre,COL.paper,1.5);pl.dot(S.b,6,COL.violet,COL.paper,1.5);
    pl.text(add(S.a,[0,-.42]),'persona A',COL.ochre,{align:'center',font:'600 12px'});pl.text(add(S.b,[0,-.42]),'persona B',COL.violet,{align:'center',font:'600 12px'});
    pl.text([BOXM.x0+.2,BOXM.y1-.3],'orange dashed: straight blend · navy: geodesic through the data',COL.ink,{font:'600 12px'});
    const samp=Array.from({length:61},(_,i)=>gap(at(straight,i/60)));
    reads('#m_mf',[[f2(S.dg/S.de),'d_geodesic / d_straight'],[samp.reduce((a,b)=>Math.max(a,b),0).toFixed(1)+'σ','straight path: largest gap from the data'],[pct(avg(samp.map(x=>x>3?1:0))),'straight path more than 3σ from any token'],
      [gap(ms).toFixed(1)+'σ / '+gap(mg).toFixed(1)+'σ','gap at t: straight / geodesic']])}
  slider('r_mfb',v=>(v/100).toFixed(2),v=>{bend=v/100;S=null;draw()});slider('r_mft',v=>(v/100).toFixed(2),v=>{t=v/100;draw()});
  const c2=$('#c_mf2');const drawRep=()=>{loadCols();lineChart(c2,{x:{min:0,max:1,ticks:[0,.25,.5,.75,1],label:'blend position t'},y:{min:.4,max:.75,ticks:[.4,.5,.6,.7],fmt:v=>v.toFixed(1)},
    series:[{pts:[[0,.72],[.25,.54],[.5,.43],[.75,.57],[1,.72]],col:COL.edit,dash:[6,4],marker:3.5,label:'straight blend',labelDy:14,labelBase:'top'},
            {pts:[[0,.72],[.25,.69],[.5,.66],[.75,.68],[1,.72]],col:COL.navy,marker:3.5,label:'geodesic blend'}]})};
  watch(c2,drawRep);
})();

/* ================= curved geometry: keep the length, turn the direction ================= */
(function(){let mode='both',t=.7;const r=mulberry32(77);
  const aDir=unit([-.6,.3,.74]),pDir=unit([.62,.32,.72]);
  const jit=(u,s)=>unit(add(u,[s*randn(r),s*randn(r),s*randn(r)]));
  const CA=[],CP=[];for(let i=0;i<46;i++){CA.push(jit(aDir,.14));CP.push(jit(pDir,.14))}
  const h0=jit(aDir,.1),pm=unit(meanOf(CP)),d=sub(meanOf(CP),meanOf(CA));
  const slerp=(a,b,s)=>{const th=Math.acos(clamp(dot(a,b),-1,1));if(th<1e-6)return a;return add(scl(a,Math.sin((1-s)*th)/Math.sin(th)),scl(b,Math.sin(s*th)/Math.sin(th)))};
  const angDeg=(a,b)=>Math.acos(clamp(dot(unit(a),unit(b)),-1,1))*180/Math.PI;
  const pl=new Plot3D($('#c_sp'),draw,{yaw:-.45,pitch:.3,span:1.5});
  // points just outside the unit sphere, where the labels sit, so the globe and its labels fill the canvas
  const SPB=[];for(let i=0;i<40;i++){const z=-1+2*(i+.5)/40,rr=Math.sqrt(1-z*z),a=i*2.4;SPB.push(scl([rr*Math.cos(a),rr*Math.sin(a),z],1.2))}
  function draw(){if(!pl.ready())return;loadCols();pl.clear();pl.fit(SPB);
    for(let lat=-60;lat<=60;lat+=30){const z=Math.sin(lat*Math.PI/180),rr=Math.cos(lat*Math.PI/180),ring=[];for(let i=0;i<=72;i++){const a=i/72*2*Math.PI;ring.push([rr*Math.cos(a),rr*Math.sin(a),z])}pl.poly(ring,A(COL.muted,.22),1)}
    for(let lon=0;lon<180;lon+=30){const a=lon*Math.PI/180,mer=[];for(let i=0;i<=72;i++){const b=i/72*2*Math.PI;mer.push([Math.cos(b)*Math.cos(a),Math.cos(b)*Math.sin(a),Math.sin(b)])}pl.poly(mer,A(COL.muted,.22),1)}
    pl.poly([[0,0,0],aDir],A(COL.assist,.6),1.2,{dash:[3,3]});pl.poly([[0,0,0],pm],A(COL.persona,.6),1.2,{dash:[3,3]});
    const pts=[];CA.forEach(p=>pts.push({p,r:2.4,fill:A(COL.assist,.55)}));CP.forEach(p=>pts.push({p,r:2.4,fill:A(COL.persona,.7)}));pl.points(pts);
    pl.text([0,0,-.08],'zero vector',COL.muted,'500 11px');pl.points([{p:[0,0,0],r:3,fill:COL.ink}]);
    const steps=40,addP=[],rotP=[];for(let i=0;i<=steps;i++){const s=t*i/steps;addP.push(add(h0,scl(d,s)));rotP.push(slerp(h0,pm,s))}
    if(mode!=='rotate'){pl.poly(addP,COL.edit,2.4);pl.points([{p:addP[steps],r:5,fill:COL.edit,stroke:COL.paper,lw:1.5}])}
    if(mode!=='add'){pl.poly(rotP,COL.navy,2.4);pl.points([{p:rotP[steps],r:5,fill:COL.navy,stroke:COL.paper,lw:1.5}])}
    pl.points([{p:h0,r:5.5,fill:COL.paper,stroke:COL.drift,lw:2}]);
    pl.text(add(aDir,scl(aDir,.16)),'assistant',COL.assist);pl.text(add(pm,scl(pm,.16)),'persona',COL.persona);
    const ea=addP[steps],er=rotP[steps];const minAdd=Math.min(...addP.map(nrm));
    reads('#m_sp',[[f2(nrm(ea)),'length after adding (start = 1)'],[f2(minAdd),'shortest length along the added path'],[f2(nrm(er)),'length after rotating'],
      [angDeg(ea,pm).toFixed(0)+'° / '+angDeg(er,pm).toFixed(0)+'°','angle to the persona: added / rotated']])}
  seg('#s_sp',[['add','Add'],['rotate','Rotate'],['both','Both']],mode,v=>{mode=v;draw()});
  slider('r_spt',v=>(v/100).toFixed(2),v=>{t=v/100;draw()});
})();

/* ================= curved geometry: sharp directions of the behaviour loss ================= */
(function(){let share=.03,ratio=79;const af=35*Math.PI/180,f=[Math.cos(af),Math.sin(af)],s=[-Math.sin(af),Math.cos(af)];
  const pl=new Plot2D($('#c_sh'),{x0:-1,x1:4.2,y0:-.7,y1:3.1},draw);
  const ratioOf=v=>5*Math.pow(10,2*v/100);
  function draw(){if(!pl.ready())return;loadCols();pl.clear();
    const v=scl(add(scl(f,Math.sqrt(1-share)),scl(s,Math.sqrt(share))),3),vc=scl(f,3*Math.sqrt(1-share));
    pl.line(sub(v,scl(s,1.3)),add(v,scl(s,1.3)),A(COL.violet,.7),1.2,[4,4]);pl.text(add(v,scl(s,1.45)),'sharp direction',COL.violet,{align:'center'});
    pl.line(sub(v,scl(f,1.2)),add(v,scl(f,.9)),A(COL.muted,.7),1.2,[4,4]);pl.text(add(v,scl(f,1.05)),'flat',COL.muted);
    [.02,.08,.18,.32].forEach(c=>pl.ellipse(v,[f,s],[Math.sqrt(2*c),Math.sqrt(2*c/ratio)],A(COL.navy,.45),{w:1}));
    pl.arrow([0,0],v,COL.edit,2.6,10);pl.arrow([0,0],vc,COL.navy,2.4,9);pl.line(vc,v,COL.edit,1.4,[3,3]);
    pl.dot([0,0],3.5,COL.ink);pl.text([.08,-.25],'origin of steering-vector space',COL.muted);
    pl.text(add(scl(v,.5),scl(s,.25)),'original v',COL.edit,{align:'center',font:'600 12px'});pl.text(add(scl(vc,.62),scl(s,-.28)),'sharp part removed',COL.navy,{align:'center',font:'600 12px'});
    const before=(1-share)+share*ratio;
    reads('#m_sh',[[(Math.sqrt(1-share)).toFixed(3),'cosine, original vs cleaned'],['−'+(100*(1-Math.sqrt(1-share))).toFixed(1)+'%','length change'],
      [before.toFixed(1)+' → 1.0','directional curvature vᵀHv/|v|² (flat = 1)'],[(before).toFixed(1)+'×','curvature reduction']])}
  slider('r_shs',v=>(v/10).toFixed(1)+'%',v=>{share=v/1000;draw()});slider('r_shk',v=>ratioOf(v).toFixed(0),v=>{ratio=ratioOf(v);draw()});
})();

/* ================= over turns: holding is control ================= */
(function(){const TURNS=20,TPT=12,NT=TURNS*TPT;const PUSH=[5,13],PROBE=[8,16];let seed=3;
  let P=.8,mem=.6,gamma=.3,tau=.6,ck=10;const PULL={1:.11,3:.20,10:.33,30:.49,100:.68};
  const CTRL=[{id:'none',label:'Prompt alone',c:'muted',on:true},{id:'vector',label:'Vector',c:'edit',on:true},{id:'cap',label:'Cap',c:'assist',on:true},
    {id:'partial',label:'Partial correction',c:'navy',on:false},{id:'ctok',label:'Conceptor pull',c:'persona',on:true},{id:'antic',label:'Cap + anticipation',c:'drift',on:false},
    {id:'integral',label:'Integral action',c:'violet',on:false},{id:'attractor',label:'Attractor with memory',c:'ochre',on:false}];
  loadCols();const box=$('#k6');CTRL.forEach(c=>{const l=document.createElement('label');const inp=document.createElement('input');inp.type='checkbox';inp.id='k6-'+c.id;inp.checked=c.on;
    const sw=document.createElement('i');sw.className='sw ln';sw.style.background=`var(--${c.c})`;l.append(inp,sw,document.createTextNode(c.label));
    inp.addEventListener('change',()=>{c.on=inp.checked;draw()});box.appendChild(l)});
  function sim(id){const r=mulberry32(seed);let s=1,b=1,I=0,z=0,acc=0;const xs=[],us=[];
    for(let i=0;i<NT;i++){const turn=Math.floor(i/TPT)+1;const hit=PUSH.includes(turn)||PROBE.includes(turn);let m=b;if(PUSH.includes(turn))m-=P;if(PROBE.includes(turn))m-=.6*P;
      s=s+.22*(m-s)+.04*randn(r);let u=0;const tEff=id==='antic'&&hit?tau+.25:tau;
      if(id==='vector')u=.09;
      else if((id==='cap'||id==='antic')&&s<tEff)u=tEff-s;
      else if(id==='partial'&&s<tau)u=gamma*(tau-s);
      else if(id==='ctok')u=PULL[ck]*(1-s);
      else if(id==='integral'){const e=Math.max(0,tau-s);I=.96*I+e;u=.25*e+.06*I}
      else if(id==='attractor'){z=.9*z+.1*(1-s);u=.45*z}
      s+=u;xs.push(s);us.push(Math.abs(u));acc+=s;
      if((i+1)%TPT===0){const turnAvg=acc/TPT;acc=0;if(hit&&turnAvg<b)b+=mem*(turnAvg-b)}}
    const late=xs.slice(16*TPT);
    return{xs,inChar:avg(xs.map(x=>x>=.5?1:0)),late:avg(late.map(x=>x>=.5?1:0)),edit:us.reduce((a,c)=>a+c,0),over:avg(xs.map(x=>Math.max(0,x-1.15)))}}
  const cv=$('#c6'),g=cv.getContext('2d');watch(cv,()=>draw());
  function draw(){const rc=fitCanvas(cv,g);if(!rc)return;loadCols();
    const W=rc.width,H=rc.height,pad={l:40,r:12,t:26,b:26},y0=-.4,y1=1.7;const X=i=>pad.l+i/(NT-1)*(W-pad.l-pad.r),Y=v=>pad.t+(y1-v)/(y1-y0)*(H-pad.t-pad.b);
    const font=FONT();g.font=`500 11px ${font}`;
    g.fillStyle=A(COL.persona,.08);g.fillRect(pad.l,Y(1.15),W-pad.l-pad.r,Y(.5)-Y(1.15));
    for(let tn=1;tn<=TURNS;tn++){const x=X((tn-1)*TPT);g.strokeStyle=COL.grid;g.lineWidth=1;g.beginPath();g.moveTo(x,pad.t);g.lineTo(x,H-pad.b);g.stroke();
      if(PUSH.includes(tn)||PROBE.includes(tn)){g.fillStyle=A(PUSH.includes(tn)?COL.drift:COL.ochre,.1);g.fillRect(x,pad.t,X(TPT)-X(0),H-pad.t-pad.b)}
      if(tn%2===1||tn===20){g.fillStyle=COL.muted;g.textAlign='center';g.textBaseline='top';g.fillText(String(tn),x+(X(TPT)-X(0))/2,H-pad.b+5)}}
    g.textAlign='left';g.textBaseline='bottom';g.fillStyle=COL.drift;g.fillText('drop the act: turns 5, 13',pad.l+4,pad.t-6);g.fillStyle=COL.ochre;g.fillText('are you an AI?: turns 8, 16',pad.l+190,pad.t-6);
    g.textAlign='right';g.textBaseline='middle';g.fillStyle=COL.muted;[0,.5,1,1.5].forEach(v=>{g.fillText(v.toFixed(1),pad.l-6,Y(v));g.strokeStyle=COL.hair;g.beginPath();g.moveTo(pad.l,Y(v));g.lineTo(W-pad.r,Y(v));g.stroke()});
    g.strokeStyle=A(COL.navy,.6);g.setLineDash([5,4]);g.beginPath();g.moveTo(pad.l,Y(tau));g.lineTo(W-pad.r,Y(tau));g.stroke();g.setLineDash([]);
    g.save();g.translate(12,pad.t+(H-pad.t-pad.b)/2);g.rotate(-Math.PI/2);g.textAlign='center';g.fillStyle=COL.muted;g.fillText('persona coordinate (1 = persona)',0,0);g.restore();
    const rows=[];CTRL.forEach(c=>{const s=sim(c.id);rows.push([c,s]);if(!c.on)return;g.strokeStyle=COL[c.c];g.lineWidth=c.id==='none'?1.4:1.9;g.beginPath();s.xs.forEach((v,i)=>{const x=X(i),y=Y(clamp(v,y0,y1));i?g.lineTo(x,y):g.moveTo(x,y)});g.stroke()});
    $('#t6').innerHTML='<thead><tr><th>Toy controller</th><th>tokens in character (≥ 0.5)</th><th>turns 17-20 in character</th><th>total edit</th><th>overshoot past 1.15</th></tr></thead><tbody>'+
      rows.map(([c,s])=>`<tr><td><i class="sw ln" style="background:var(--${c.c})"></i> ${c.label}${c.id==='ctok'?` (k = ${ck})`:''}</td><td class="num">${pct(s.inChar)}</td><td class="num">${pct(s.late)}</td><td class="num">${s.edit.toFixed(1)}</td><td class="num">${s.over.toFixed(3)}</td></tr>`).join('')+'</tbody>'}
  slider('r6p',v=>(v/100).toFixed(2),v=>{P=v/100;draw()});slider('r6m',v=>(v/100).toFixed(2),v=>{mem=v/100;draw()});
  slider('r6g',v=>(v/100).toFixed(2),v=>{gamma=v/100;draw()});slider('r6t',v=>(v/100).toFixed(2),v=>{tau=v/100;draw()});
  seg('#s6k',[[1,'pull at k = 1'],[3,'k = 3'],[10,'k = 10'],[30,'k = 30'],[100,'k = 100']],ck,v=>{ck=v;draw()});
  $('#b6r').addEventListener('click',()=>{seed=(seed*7919+13)%100000;draw()});
  const NP=DATA.nopush;const cell=x=>x&&x.std!=null?`${pct(x.std)} → ${pct(x.nopush)}`:'n/a';
  $('#t6r').innerHTML='<thead><tr><th>Real, SmolLM3: turns 17-20 in character, with pushes → without</th><th>prompt alone</th><th>vector</th><th>cap</th><th>conceptor, k = 10</th></tr></thead><tbody>'+
    Object.keys(NP).map(p=>`<tr><td>${p}</td><td class="num">${cell(NP[p].none)}</td><td class="num">${cell(NP[p].add)}</td><td class="num">${cell(NP[p].cap)}</td><td class="num">${cell(NP[p].ctok_tight)}</td></tr>`).join('')+'</tbody>';
})();

/* ================= persona space (3D) ================= */
(function(){const r=mulberry32(21);const muA=[-1.8,0,0],core=[3.6,0,0];
  const G=[{n:'assistant',c:'assist',mu:muA,sp:[0,0,0]},
    {n:'pirate',c:'persona',f:1,sp:[0,1.4,.5]},{n:'ghost',c:'violet',f:.95,sp:[0,-.7,1.4]},{n:'bard',c:'edit',f:.9,sp:[0,1.1,-1]},
    {n:'genie',c:'drift',f:1.05,sp:[0,-1.3,-.6]},{n:'consultant',c:'ochre',f:.35,sp:[0,-.3,-.4]}];
  G.forEach(gr=>{if(gr.n!=='assistant')gr.mu=add(add(muA,scl(core,gr.f)),gr.sp)});
  const cu=unit([.45,.75,.48]);let o1=unit([-cu[1],cu[0],0]);const o2=[cu[1]*o1[2]-cu[2]*o1[1],cu[2]*o1[0]-cu[0]*o1[2],cu[0]*o1[1]-cu[1]*o1[0]];
  G.forEach(gr=>{gr.pts=[];for(let i=0;i<70;i++)gr.pts.push(add(gr.mu,add(add(scl(cu,.9*randn(r)),scl(o1,.22*randn(r))),scl(o2,.22*randn(r)))))});
  const mA=meanOf(G[0].pts);const means=G.map(gr=>meanOf(gr.pts));const gm=meanOf(means);
  const SigB=covOf(means);let SigW=[[0,0,0],[0,0,0],[0,0,0]];G.forEach(gr=>{SigW=madd(SigW,covOf(gr.pts))});SigW=mscl(SigW,1/G.length);
  const pca=symEig(SigB);const Wih=symFn(SigW,v=>1/Math.sqrt(Math.max(v,1e-9)));const lda=symEig(mm(mm(Wih,SigB),Wih));const ldaDirs=lda.vecs.map(v=>unit(mv(Wih,v)));
  const Rs=G.map(gr=>momentAbout(gr.pts,mA));const personas=[1,2,3,4,5];
  let view='clouds',sel=1,k=1;const pl=new Plot3D($('#c8'),draw,{yaw:-.75,pitch:.35,span:4.8});
  const I3=eye(3);const quota=C=>(C[0][0]+C[1][1]+C[2][2])/3;
  function andNot(Ci,Co){return inv(msub(madd(inv(Ci),inv(msub(I3,Co))),I3))}
  function drawC(C,col){const{vals,vecs}=symEig(C);pl.ellipsoid(mA,vecs,vals.map(v=>Math.max(v,.03)*3.6),A(col,.55))}
  const ALL8=[].concat(...G.map(gr=>gr.pts));
  function draw(){if(!pl.ready())return;loadCols();pl.clear();pl.fit(ALL8);pl.axes3([-4,-3.6,-2.2],1,['x','y','z']);
    const pts=[];G.forEach(gr=>gr.pts.forEach(p=>pts.push({p,r:2.2,fill:A(COL[gr.c],view==='clouds'?.75:.4)})));pl.points(pts);
    G.forEach((gr,i)=>pl.text(add(means[i],[0,0,gr.n==='consultant'||gr.n==='bard'?-1.05:1.05]),gr.n,COL[gr.c]));
    let rd=[];
    if(view==='pca'){pca.vecs.forEach((v,i)=>{const L=1.6*Math.sqrt(Math.max(pca.vals[i],0))+.3;pl.arrow(gm,add(gm,scl(v,L)),COL.navy,2.4-i*.5);pl.text(add(gm,scl(v,L+.35)),'PC'+(i+1),COL.navy)});
      const tot=pca.vals.reduce((a,b)=>a+b,0);rd=[[pca.vals.map(v=>pct(v/tot)).join(' / '),'variance of means per PC'],[f2(Math.abs(dot(pca.vecs[0],unit(core)))),'cos(PC1, shared core)']]}
    else if(view==='lda'){ldaDirs.forEach((v,i)=>{if(i>1&&lda.vals[i]<1e-6)return;const L=2.3-i*.55;pl.arrow(gm,add(gm,scl(v,L)),COL.violet,2.4-i*.5);pl.text(add(gm,scl(v,L+.35)),'LD'+(i+1),COL.violet)});
      const tot=lda.vals.reduce((a,b)=>a+Math.max(b,0),0);rd=[[lda.vals.map(v=>pct(Math.max(v,0)/tot)).join(' / '),'separation per discriminant axis'],[f2(Math.abs(dot(ldaDirs[0],unit(core)))),'cos(LD1, shared core)']]}
    else if(view==='or'){let R=[[0,0,0],[0,0,0],[0,0,0]];personas.forEach(i=>{R=madd(R,Rs[i])});R=mscl(R,1/personas.length);const C=conceptor(R,k);drawC(C,COL.navy);
      const{vals,vecs}=symEig(C);pl.arrow(mA,add(mA,scl(vecs[0],vals[0]*3.6*Math.sign(dot(vecs[0],core)||1))),COL.navy,2.4);
      rd=[[f2(quota(C)),'quota of persona space (OR)'],[f2(Math.abs(dot(vecs[0],unit(core)))),'cos(top direction, shared core)']]}
    else if(view==='andnot'){const rest=personas.filter(i=>i!==sel);let Ro=[[0,0,0],[0,0,0],[0,0,0]];rest.forEach(i=>{Ro=madd(Ro,Rs[i])});Ro=mscl(Ro,1/rest.length);
      const Ci=conceptor(Rs[sel],k),Co=conceptor(Ro,k),Cx=andNot(Ci,Co);drawC(Ci,COL[G[sel].c]);drawC(Cx,COL.ink);
      const{vals,vecs}=symEig(Cx);const off=G[sel].sp;let v0=vecs[0];if(dot(v0,sub(means[sel],mA))<0)v0=scl(v0,-1);pl.arrow(mA,add(mA,scl(v0,Math.max(vals[0],.08)*3.6*1.4)),COL.ink,2.6);
      rd=[[f2(quota(Ci))+' → '+f2(quota(Cx)),'quota: '+G[sel].n+' → AND NOT rest'],[f2(Math.abs(dot(v0,unit(off)))),'cos(kept direction, true '+G[sel].n+' offset)'],[f2(Math.abs(dot(v0,unit(core)))),'cos(kept direction, shared core)']]}
    else{rd=[['6','groups'],['70','tokens each']]}
    pl.arrow(mA,add(mA,core),A(COL.gold,.95),2.2);pl.text(add(mA,scl(core,.5)),'shared core',COL.ochre,'600 11px');
    reads('#m8',rd)}
  seg('#s8v',[['clouds','Clouds'],['pca','PCA of means'],['lda','Discriminant axes'],['or','Persona space (OR)'],['andnot','AND NOT the rest']],view,v=>{view=v;draw()});
  seg('#s8p',personas.map(i=>[i,G[i].n]),sel,v=>{sel=v;draw()});
  slider('r8a',v=>Math.pow(10,v/100).toFixed(2),v=>{k=Math.pow(10,v/100);draw()});
})();

/* ================= the comparison table and the sources ================= */
(function(){const M=DATA.means;
  const hold=key=>{const s=M.smol[key],o=M.olmo[key];const f=x=>x?`${pct(x.ord)} / ${pct(x.push)} / ${f0(x.coh)}`:null;
    const parts=[];if(s)parts.push(`SmolLM3 ${f(s)}`);if(o)parts.push(`OLMo ${f(o)}`);return parts.join('<br>')};
  const NR='<span class="none">not run</span>';
  const R=[
    ['What we ran'],
    ['Steering vector (ActAdd, CAA, persona vectors)','every token','add c·d','mean difference of two prompt conditions','single-turn behaviour and trait steering on Llama 2 and later models; persona vectors also monitor traits during training',hold('add')],
    ['Activation cap, one layer','token below a floor','lift to the floor along one axis','persona axis plus a percentile floor','Assistant Axis: capping the assistant axis cut harmful jailbreak responses by about 60% (single-turn)',hold('cap')],
    ['Activation cap, Assistant Axis style','below a floor, six layers','lift to the floor at each layer','an axis and floor per layer','as above',hold('cap_aa')],
    ['Conceptor, median aperture (ours)','every token','shrink toward the persona mean, per direction','per-token persona covariance','function steering on GPT-J 81.6% against 32.0% for addition (Postmus & Abreu); semantic steering win rates 0.70-0.82 against 0.50-0.62 (Triantafyllopoulos et al.); single-turn',hold('conceptor_tok')],
    ['Conceptor, aperture 10x (ours)','every token','same, with a = 10 × median','same','no published multi-turn test',hold('ctok_tight')+'<br>AI admissions 38% on SmolLM3'],
    ['Conceptor + cap (ours)','every token, then below a floor','shrink, then clamp','both fits','none',hold('ctok_cap')],
    ['Vector + cap (ours)','every token, then below a floor','add, then clamp','both fits','none',hold('add_cap')],
    ['Mean-shift control (ours)','every token','pull to the persona mean','persona mean only','the matrix-removed control of Razdan & Balamurugan',hold('meanshift_tok')],
    ['Difference conceptor, diffpull (ours)','every token','pull along the paired-difference subspace','persona minus assistant answers to the same question','none',hold('diffpull')],
    ['Fisher-gated cap, fisher_cap (ours)','Fisher score below a floor','lift along d (data-metric edit)','Fisher direction, percentile floor','none; our proposal',hold('fisher_cap')+'<br>at a lower strength than the cap'],
    ['Region (ours)','outside an ellipse in discriminative coordinates','pull back to the ellipse along d and identity','Fisher score and an identity probe','none; our proposal',hold('region')+'<br>AI admissions 25% on SmolLM3'],
    ['How to move a token'],
    ['LiSeCo','probe score outside a band','minimum-norm move onto the band','a linear probe per layer','English to Spanish, P(Spanish) 0.91-0.99 across three models (single-turn)',NR],
    ['Directional ablation','every token','remove one direction','mean difference','refusal is carried by one direction in 13 chat models up to 72B',NR],
    ['LEACE','every token','closed-form least-squares erasure','labelled representations','no linear classifier can recover the concept afterwards',NR],
    ['PaSS on an INLP subspace','prompt tokens','scale the persona component by β','INLP on activations with and without the persona instruction','emoji persona score −54.0 / +71.4 against −16.7 / +30 for a mean-difference vector (Llama-3-8B, single-turn)',NR],
    ['MiMiC (Gaussian transport)','states nearer the source mean','affine map matching mean and covariance','class means and covariances','GPT-2 large toxicity 0.39 to 0.29, perplexity 24.7 to 30.7 (single-turn)',NR],
    ['Spherical steering','gated by confidence','rotate along a great circle, keep the length','a target direction','about +10 points over addition on TruthfulQA, COPA, StoryCloze',NR],
    ['Angular steering','not stated in the abstract','rotate within a fixed 2D plane','a feature direction','refusal and emotion steering (NeurIPS 2025)',NR],
    ['Householder pseudo-rotation','every token','reflection-based rotation, keeps the length','a target direction','safety benchmarks',NR],
    ['When to act'],
    ['CAST','once per prompt','add the vector to every token of the answer, or none','condition and behaviour vectors (PCA of contrastive states)','refusal on harmless prompts 96.4% to 2.2% while harmful stays 90.7% (Qwen1.5-1.8B, single-turn)',NR],
    ['DSAS','soft logistic gate per token','blend the original and steered state','a per-layer classifier','toxicity 13.67 to 8.64 for CAA on Qwen2.5-1.5B (single-turn)',NR],
    ['GAPS','per neuron and per token','steer only separable, source-like neurons','per-neuron AUROC and Gaussians','Gemma-3 4B toxicity 3.52% to 0.48% at a fixed capability budget (single-turn)',NR],
    ['Which directions to fit'],
    ['Contrastive covariance subspaces (CCS)','every token','add a projected mean difference','scatter of the target class minus nuisance classes','Qwen3-8B, 20-turn dialogues: concept-and-fluent rate 93% to 80%, against 36% to 10% for CAA and 91% to 71% for a system prompt',NR],
    ['SEA (spectral editing)','every token','project onto positive-covarying directions, off negative ones','cross-covariance with positive and negative demonstrations','TruthfulQA MC1 36.96 to 39.41 (Llama-2-7B-chat, single-turn)',NR],
    ['SAE trait routing','a routing module picks facet vectors per context','add the selected facet vectors to the residual stream','a contrastive sparse autoencoder on a 15,000-sample Big Five facet corpus','beat CAA and prompt-only baselines on character fidelity; SAE plus prompt did best',NR],
    ['Moving distributions'],
    ['Influence-weighted transport','every token','optimal transport toward influential concept examples','influence scores of the concept examples','beats activation-transport baselines on toxicity, concept induction and truthfulness',NR],
    ['Persona Dosing','every position','a learned flow, strength = flow time','a learned velocity field conditioned on the trait text','core-trait expression at coherence ≥ 75: 75-86 against 42-68 for CAA (single-turn)',NR],
    ['Cobras','query-adaptive','Schrödinger bridge on the sphere of directions','the two activation distributions','beats prior steering in nearly all model-task settings while largely keeping OOD performance',NR],
    ['Curved geometry'],
    ['Manifold steering','not stated','move along a fitted activation manifold','a manifold fit to activations','linear steering cut off-manifold and gave unnatural outputs; manifold steering followed natural behaviour paths',NR],
    ['PersonaManifold geodesic steering','not stated','interpolate personas along graph geodesics','about 2,000 persona means','coherence at the blend midpoint 0.66 against 0.43 for a straight-line blend',NR],
    ['Sharp-direction removal','every token','drop the steering Hessian’s top directions from v','the steering Hessian','cosine to the original above 0.974; beat CAA in all 25 open-ended conditions',NR],
    ['Over turns'],
    ['Attractor control (CAL)','every token','a latent with memory pulls toward the persona centre','reframing and stress corpora','100-turn dialogues with a shock at turn 50: human recovery rating 4.07 against 3.42 for ActAdd and 2.77 for a prompt',NR],
    ['PID steering','every layer','PID combination of per-layer mean differences','source and target sets','jailbreak success 94.85 against 93.26 for difference-in-means (Llama-3.1-8B); the feedback runs across layers',NR],
    ['Persona space'],
    ['BILLY','not stated','blend several persona vectors','several persona vectors','creative generation; merge rule in the paper',NR],
  ];
  // each method's paper, as links under its name
  const NAMEREF={'Steering vector (ActAdd, CAA, persona vectors)':['actadd','caa','pv'],'Activation cap, one layer':['axis'],'Activation cap, Assistant Axis style':['axis'],
    'Conceptor, median aperture (ours)':['jaeger','postmus','triant'],'Mean-shift control (ours)':['razdan'],'LiSeCo':['liseco'],'Directional ablation':['arditi'],'LEACE':['leace'],
    'PaSS on an INLP subspace':['pass','inlp'],'MiMiC (Gaussian transport)':['mimic'],'Spherical steering':['spherical'],'Angular steering':['angular'],'Householder pseudo-rotation':['hpr'],
    'CAST':['cast'],'DSAS':['dsas'],'GAPS':['gaps'],'Contrastive covariance subspaces (CCS)':['ccs'],'SEA (spectral editing)':['sea'],'SAE trait routing':['sae'],
    'Influence-weighted transport':['influence'],'Persona Dosing':['dosing'],'Cobras':['cobras'],'Manifold steering':['manifold'],'PersonaManifold geodesic steering':['pm'],
    'Sharp-direction removal':['azizi'],'Attractor control (CAL)':['cal'],'PID steering':['pid'],'BILLY':['billy']};
  const nameCell=n=>`<b>${n}</b>`+(NAMEREF[n]?`<br><span class="src">${NAMEREF[n].map(k=>cite(k)).join('; ')}</span>`:'');
  $('#t_all').innerHTML='<thead><tr><th>Method</th><th>When it acts</th><th>How it moves h</th><th>Fit on</th><th>Published evidence and setting</th><th>Our holds (ordinary / pushes / coherence)</th></tr></thead><tbody>'+
    R.map(row=>row.length===1?`<tr class="grp"><td colspan="6">${row[0]}</td></tr>`:`<tr><td>${nameCell(row[0])}</td><td>${row[1]}</td><td>${row[2]}</td><td>${row[3]}</td><td>${row[4]}</td><td class="${row[5]===NR?'':'ours num'}">${row[5]}</td></tr>`).join('')+'</tbody>';
  // the reference list, built from REF so every entry opens the paper itself in a new tab
  const ol=$('#refs');Object.values(REF).sort((a,b)=>a.a.localeCompare(b.a)).forEach(r=>{const li=document.createElement('li');
    li.innerHTML=`${escH(r.a)}. <a href="${r.url}" target="_blank" rel="noopener">${escH(r.t)}</a>.${r.v?' '+escH(r.v)+'.':''}${r.x?' arXiv '+r.x+'.':' Conference PDF.'}`;ol.appendChild(li)});
})();
